<!--vbase-->
<template>
  <div class="row" :style="workflowdashboardActive ? 'flex-grow: 0;' : ''">
    <template v-if="!workflowdashboardActive">
      <div class="col-12 q-mb-md row items-center">
          <div class="col-sm-8 col-md-4 col-lg-4">
            <q-input
              v-model="searchBy"
              dense
              :class="
                searchBy.length === 0 ? 'search-in-active' : 'search-active'
              "
              autofocus
              :placeholder="$t('search_workflow_test_scenario')"
              outlined
              @update:model-value="inputValueChanges()"
            >
              <template v-slot:append>
                <q-icon flat dense name="search" size="24px" color="primary" />
              </template>
            </q-input>
          </div>
          <q-select
            class="col-auto q-pl-sm"
            dense
            outlined
            v-model="selected"
            :options="options"
            multiple
            emit-value
            map-options
            :label="$t('filters')"
            option-value="value"
            option-label="label"
          >
            <template v-slot:option="scope">
              <q-item v-bind="scope.itemProps" clickable>
                <q-item-section side>
                  <q-checkbox
                    :model-value="scope.selected"
                    @update:model-value="scope.toggleOption(scope.opt)"
                  />
                </q-item-section>

                <q-item-section>
                  <q-item-label>{{ scope.opt.label }}</q-item-label>
                </q-item-section>
              </q-item>
            </template>
          </q-select>
          <div class="col-auto q-pl-sm">
            <div class="clear-button" @click="clearFilters">
              <q-icon name="clear" size="xs" />
              <span>{{ $t('clear') }}</span>
            </div>
          </div>
          <div class="col text-right">
            <f-btn
              icon="play_arrow"
              @click="runAllTests"
              :label="$t('run_all_test')"
              :disable="testProgressBanner.visible"
              class="q-mr-sm"
            />
            <f-btn
              icon="upload"
              @click="workflowTestDialog = true"
              :label="$t('add_test_scenario')"
            />
          </div>

      </div>
    </template>

    <!-- Simple DocBitsTable for dashboard mode -->
    <DocBitsTable
      v-if="workflowdashboardActive"
      :rows="tableData"
      :columns="dashboardColumns"
      row-key="id"
      :features="{ sorting: false, pagination: false }"
      dense
    >
      <template #body-cell-test_scenario_name="{ row }">
        <span :class="row.enabled === true ? 'color-primary' : 'disabled-name'">
          {{ row.test_scenario_name }}
        </span>
      </template>
      <template #body-cell-status="{ row }">
        <q-icon
          v-if="row.status === 'Pass'"
          name="check_circle"
          class="bg-icon-30a79e"
          size="sm"
        />
        <q-icon
          v-else-if="row.status === null || row.status === 'failed_condition'"
          name="do_not_disturb_on"
          color="orange"
          size="sm"
        />
        <q-icon
          v-else-if="row.status"
          name="cancel"
          color="red"
          size="sm"
        />
      </template>
    </DocBitsTable>

    <!-- Full DocBitsTable for standalone page -->
    <DocBitsTable
      v-else
      class="col-12"
      :rows="tableData"
      :columns="tableColumns"
      :features="{
        ...tableFeatures,
        pagination: true,
        rowActions: true,
      }"
      :row-actions="rowActions"
      :pagination="tablePagination"
      :loading="false"
      row-key="id"
      table-id="workflow-test-manager-table"
      :no-data-label="'workflow_test_scenario_not_found'"
      :table-height="'calc(100vh - 200px)'"
      @row-click="handleRowClick"
      @row-action="handleRowAction"
      @update:pagination="handlePaginationChange"
    >
      <!-- Custom name column with status icon -->
      <template #body-cell-test_scenario_name="{ row }">
        <template v-if="row.status">
          <q-icon
            v-if="row.status === 'Pass'"
            name="check_circle"
            class="bg-icon-30a79e mr-4"
            size="sm"
          />
          <q-icon
            v-else-if="row.status === null || row.status === 'failed_condition'"
            name="do_not_disturb_on"
            class="mr-4"
            color="orange"
            size="sm"
          />
          <q-icon
            v-else
            name="cancel"
            color="red"
            size="sm"
            class="mr-4"
          />
        </template>
        <span
          class="font-size-16"
          :class="row.enabled === true ? 'color-primary' : 'disabled-name'"
        >
          {{ row.test_scenario_name }}
        </span>
      </template>

      <!-- Custom detail column -->
      <template #body-cell-detail>
        <span>{{ $t('VIEW_DETAILS') }}</span>
      </template>
    </DocBitsTable>
  </div>

  <q-dialog v-model="confirmDelete" persistent>
    <q-card>
      <q-card-section class="row flex-col-center">
        <q-avatar icon="warning" color="primary" />
      </q-card-section>

      <q-card-section class="row items-center">
        <span class="q-ml-sm">{{ $t('msg_delete') }}</span>
      </q-card-section>

      <q-card-actions align="right">
        <q-btn flat :label="$t('cancel')" color="primary" v-close-popup />
        <q-btn
          flat
          :label="$t('delete')"
          color="primary"
          v-close-popup
          @click="deleteTestScenario"
        />
      </q-card-actions>
    </q-card>
  </q-dialog>

  <Loader />

  <q-dialog v-model="workflowTestDialog" class="options-dialog">
    <workflowNewTestScenario
      :workflowData="workflowsData"
      :testScenario="editingTestScenario"
      @reloadData="loadWorkflowTestScenarios()"
      @Close="closeTestScenarioDialog"
    />
  </q-dialog>

  <q-dialog v-model="testScenarioDetail" class="options-dialog">
    <q-card class="col-12 q-mt-sm q-pa-md max-width-700-imp">
      <q-card-actions class="row">
        <div class="col-12 border-bottom-bdbdbd q-pb-sm">
          <div class="row">
            <div class="col-12 items-center">
              <div class="text-h6 text-bold text-primary flex items-center">
                <span class="workflow-title">{{
                  $t('workflow_test_scenario_details')
                }}</span>
              </div>
            </div>
          </div>
        </div>

        <div v-if="selectedRow" class="col-12 mt-4 q-pa-lg">
          <div class="row mb-10">
            <div class="col-4">{{ $t('test_scenario_name') }} :</div>
            <div class="col-8">{{ selectedRow.test_scenario_name }}</div>
          </div>
          <div class="row mb-10">
            <div class="col-4">{{ $t('status') }} :</div>
            <div class="col-8">
              <template v-if="selectedRow.status">
                <q-icon
                  v-if="selectedRow.status === 'Pass'"
                  :name="'check_circle'"
                  :color="'green'"
                  size="sm"
                />
                <q-icon
                  v-else-if="
                    selectedRow.status === null ||
                    selectedRow.status === 'failed_condition'
                  "
                  :name="'do_not_disturb_on'"
                  :color="'orange'"
                  size="sm"
                />
                <q-icon v-else :name="'cancel'" :color="'red'" size="sm" />
              </template>
              <template v-else>
                {{ $t('not_started') }}
              </template>
            </div>
          </div>

          <div class="row mb-10">
            <div class="col-4">{{ $t('wf_name') }} :</div>
            <div class="col-8">{{ selectedRow.workflow_name }}</div>
          </div>
          <div class="row mb-10">
            <div class="col-4">{{ $t('run_time_seconds') }} :</div>
            <div class="col-8">{{ selectedRow.run_time }}</div>
          </div>

          <div class="row mb-15">
            <div class="col-12">{{ $t('actual_data') }} :</div>
            <div class="col-12">
              <q-card class="q-mt-md p-4 height-150 overflow-auto">
                {{ formatJson(selectedRow.actual_document_data) }}
              </q-card>
            </div>
          </div>

          <div class="row mt-15">
            <div class="col-12">{{ $t('extracted_data') }} :</div>
            <div class="col-12">
              <q-card class="q-mt-md p-4 height-150 overflow-auto">
                {{ formatJson(selectedRow.extracted_document_data) }}
              </q-card>
            </div>
          </div>
        </div>
      </q-card-actions>
    </q-card>
  </q-dialog>

  <q-dialog v-model="testLogDialog" class="options-dialog">
    <workflowTestLogs
      :workflowLog="selectedRow"
      @Close="testLogDialog = false"
    />
  </q-dialog>

  <!-- Test Progress Dialog -->
  <q-dialog v-model="testProgressBanner.visible" persistent position="top">
    <q-card class="test-progress-dialog">
      <q-card-section class="row items-center q-pb-none">
        <q-icon name="play_circle_outline" size="24px" color="primary" class="q-mr-sm" />
        <div class="text-h6">{{ $t('running_tests') }}</div>
        <q-space />
        <div class="text-h6 text-primary">
          {{ testProgressBanner.executed }} / {{ testProgressBanner.total }}
        </div>
      </q-card-section>

      <q-card-section>
        <q-linear-progress
          :value="testProgressBanner.total > 0 ? testProgressBanner.executed / testProgressBanner.total : 0"
          color="primary"
          size="8px"
          rounded
          class="q-mb-md"
        />
        <div v-if="testProgressBanner.currentTest" class="text-body2 text-grey-7">
          <q-icon name="schedule" size="16px" class="q-mr-xs" />
          {{ $t('currently_running') }}:
          <strong>{{ testProgressBanner.currentTest }}</strong>
        </div>
      </q-card-section>
    </q-card>
  </q-dialog>
</template>

<script lang="ts">
import { notify } from 'src/components/notifications/notify';
import { debounce } from 'quasar';
import dateUtils from 'src/utils/date';
import { defineComponent, ref } from 'vue';
import helperUtil from 'src/utils/helperUtil';
import type { dynamicObj } from 'src/pages/assets';
import Loader from 'src/components/Loader.vue';
import helperMixin from 'src/mixins/helperMixin';
import { ApiExceptions } from 'src/exceptions/index';
import workflowTestLogs from './workflowTestLogs.vue';
import workflowNewTestScenario from './workflowNewTestScenario.vue';
import { workflowTestApiService, workflowApiService } from 'src/services';
import { DocBitsTable } from 'src/components/Table';
import type {
  UnifiedTableColumn,
  TableFeatures,
  RowActionItem,
  RowActionPayload,
  RowClickPayload,
  TablePaginationState,
  PaginationChangePayload,
} from 'src/components/Table';

export default defineComponent({
  name: 'workFlowTestManager',
  mixins: [helperUtil, helperMixin, dateUtils],
  components: { Loader, workflowNewTestScenario, workflowTestLogs, DocBitsTable },
  props: {
    workflowdashboardActive: {
      type: Boolean,
      required: false,
    },
  },
  data() {
    return {
      workflowId: ref(''),
      searchBy: ref(''),
      tableData: [] as any[],
      workflowsData: [] as any[],
      confirmDelete: ref(false),
      selectedRecordIndex: ref<number>(),
      selectedRow: ref<any>(null),
      editingTestScenario: ref<any>(null),
    };
  },

  async mounted() {
    this.debounceSearchInputFunc = debounce(() => {
      this.resetPagination();
      this.loadWorkflowTestScenarios();
    }, 1000);
    this.loadFilterOptions();
    await this.loadWorkflowTestScenarios();
    await this.loadWorkFlows();
  },

  watch: {
    selected: {
      handler(newVal: string[], oldVal: string[]) {
        if (newVal.includes('all') && !oldVal?.includes('all')) {
          this.selected = ['all'];
        } else if (
          oldVal?.includes('all') &&
          newVal.length > 1 &&
          newVal.includes('all')
        ) {
          this.selected = newVal.filter((v) => v !== 'all');
        }

        this.resetPagination();
        this.loadWorkflowTestScenarios();
      },
      deep: true,
    },
  },

  methods: {
    loadFilterOptions() {
      this.options = [
        { label: this.$t('all'), value: 'all' },
        { label: this.$t('sort_status_success'), value: 'success' },
        { label: this.$t('failed'), value: 'fail' },
      ];
    },

    clearFilters() {
      this.searchBy = '';
      this.selected = [];
    },

    inputValueChanges() {
      this.debounceSearchInputFunc();
    },

    formatJson(jsonData: any) {
      try {
        return JSON.stringify(
          typeof jsonData === 'string' ? JSON.parse(jsonData) : jsonData,
          null,
          2,
        );
      } catch (e: any) {
        notify.error(e);
        logError(e);
        return '';
      }
    },

    async loadWorkflowTestScenarios() {
      let response: any;
      try {
        this.showLoading();
        this.request_params = {} as dynamicObj;
        this.request_params['page'] = this.current_page;

        if (this.workflowdashboardActive) {
          this.request_params['limit'] = 3;
        } else {
          this.request_params['limit'] = this.page_size;
        }

        if (this.searchBy && this.searchBy.length > 1) {
          this.request_params['search'] = this.searchBy;
        }

        if (
          this.selected &&
          this.selected.length > 0 &&
          !this.selected.includes('all')
        ) {
          if (
            this.selected.includes('success') &&
            !this.selected.includes('fail')
          ) {
            this.request_params['status'] = 'Pass';
          } else if (
            this.selected.includes('fail') &&
            !this.selected.includes('success')
          ) {
            this.request_params['status'] = 'Fail';
          }
        }

        response = await workflowTestApiService.getWorkFlowTestScenarios(
          this.request_params,
        );

        if (!response.success) {
          throw response;
        }

        this.tableData = response.test_scenarios || [];
        this.total_records = response.total || 0;
        this.setTotalPages();
      } catch (err) {
        const msg = ApiExceptions.getErrorMessage(err as dynamicObj);
        notify.error(msg);
        logError(err);
      } finally {
        this.hideLoading();
      }
    },

    async loadWorkFlows() {
      try {
        const response = await workflowApiService.getWorkflowDashboard({});

        if (!response.success) {
          throw response;
        }

        this.workflowsData =
          response.entries?.map((item: any) => ({
            value: item.id,
            label: item.name,
          })) || [];
      } catch (err) {
        const msg = ApiExceptions.getErrorMessage(err as dynamicObj);
        notify.error(msg);
        logError(err);
      }
    },

    resetPagination() {
      this.total_pages = 0;
      this.current_page = 1;
      this.total_records = 0;
    },

    setTotalPages() {
      this.total_pages = Math.ceil(this.total_records / this.page_size);
    },

    async testScenarioRun(workflowId: string) {
      try {
        this.showLoading();
        const response =
          await workflowTestApiService.runWorkflowTest(workflowId);

        if (!response.message || response.error) {
          throw response;
        }

        const testStatus = response.result?.status;
        if (testStatus === 'Pass') {
          notify.success(this.$t('workflow_test_scenario_passed'));
        } else if (testStatus === 'Fail') {
          notify.error(
            this.$t('workflow_test_scenario_failed_check_logs'),
          );
        } else {
          notify.success(
            response.message || this.$t('workflow_test_scenario_run_success'),
          );
        }
      } catch (err) {
        const msg = ApiExceptions.getErrorMessage(err as dynamicObj);
        notify.error(msg);
        logError(err);
      } finally {
        this.hideLoading();
      }
    },

    openDetail(row: any) {
      let runTime = null;
      if (
        row.logs?.logs &&
        Array.isArray(row.logs.logs) &&
        row.logs.logs.length > 0
      ) {
        const lastElement = row.logs.logs[row.logs.logs.length - 1];
        if (
          lastElement &&
          typeof lastElement === 'object' &&
          !Array.isArray(lastElement)
        ) {
          runTime = lastElement.runtime;
        }
      }

      this.selectedRow = {
        ...row,
        run_time: runTime ? runTime : '-',
      };
    },

    editTestScenario(row: any) {
      this.editingTestScenario = { ...row };
      this.workflowTestDialog = true;
    },

    closeTestScenarioDialog() {
      this.workflowTestDialog = false;
      this.editingTestScenario = null;
    },

    async deleteTestScenario() {
      if (!this.workflowId) return;

      try {
        this.showLoading();
        const response =
          await workflowTestApiService.deleteWorkflowTestScenario(
            this.workflowId,
          );

        if (!response.success) {
          throw response;
        }

        notify.success(
          this.$t('workflow_test_scenario_deleted_success'),
        );
        this.workflowId = '';
        await this.loadWorkflowTestScenarios();
      } catch (err) {
        const msg = ApiExceptions.getErrorMessage(err as dynamicObj);
        notify.error(msg);
        logError(err);
      } finally {
        this.hideLoading();
      }
    },

    async handleActivateTest(row: any, isActive: boolean) {
      try {
        this.showLoading();
        const response = await workflowTestApiService.toggleActivateTest(
          row.id,
        );

        if (!response.success) {
          throw response;
        }

        notify.success(this.$t('MSG_SAVE'));
        row.enabled = isActive;
      } catch (err) {
        const msg = ApiExceptions.getErrorMessage(err as dynamicObj);
        notify.error(msg);
        logError(err);
      } finally {
        this.hideLoading();
      }
    },

    async runAllTests() {
      try {
        await workflowTestApiService.runAllTests((event: any) => {
          this.handleTestProgressEvent(event);
        });
      } catch (err) {
        const msg = ApiExceptions.getErrorMessage(err as dynamicObj);
        notify.error(msg);
        logError(err);
        this.testProgressBanner.visible = false;
      }
    },

    handleTestProgressEvent(data: any) {
      if (data.type === 'init') {
        this.testProgressBanner = {
          visible: true,
          total: data.total_tests,
          executed: 0,
          currentTest: '',
          passedCount: 0,
        };
      } else if (data.type === 'progress') {
        this.testProgressBanner.executed = data.executed_tests;
        this.testProgressBanner.currentTest = data.test_name || '';

        if (data.result && data.test_id) {
          const testIndex = this.tableData.findIndex(
            (test: any) => test.id === data.test_id,
          );
          if (testIndex !== -1) {
            const testStatus = data.result.result?.status || data.result.status;
            this.tableData[testIndex].status = testStatus;
            this.tableData = [...this.tableData];

            if (testStatus === 'Pass') {
              this.testProgressBanner.passedCount++;
            }
          }
        }
      } else if (data.type === 'complete') {
        this.testProgressBanner.visible = false;
        const { total, passedCount } = this.testProgressBanner;
        notify.success(
          this.$t('test_execution_summary', { passed: passedCount, total }),
        );
      } else if (data.type === 'error') {
        this.testProgressBanner.visible = false;
        notify.error(data.message);
      }
    },

    // DocBitsTable event handlers
    handleRowClick(payload: RowClickPayload) {
      this.openDetail(payload.row);
      this.testScenarioDetail = true;
    },

    handleRowAction(payload: RowActionPayload) {
      const { action, row } = payload;
      switch (action) {
        case 'run_test':
          this.testScenarioRun(row.id);
          break;
        case 'edit':
          this.editTestScenario(row);
          break;
        case 'activate':
          this.handleActivateTest(row, true);
          break;
        case 'deactivate':
          this.handleActivateTest(row, false);
          break;
        case 'logs':
          this.openDetail(row);
          this.testLogDialog = true;
          break;
        case 'delete':
          this.workflowId = row.id;
          this.confirmDelete = true;
          this.selectedRecordIndex = this.tableData.findIndex((item: any) => item.id === row.id);
          break;
      }
    },

    handlePaginationChange(payload: PaginationChangePayload) {
      this.page_size = payload.rowsPerPage;
      this.current_page = payload.page;
      this.loadWorkflowTestScenarios();
    },
  },
  computed: {
    tablePagination(): TablePaginationState {
      return {
        sortBy: null,
        descending: false,
        page: this.current_page,
        rowsPerPage: this.page_size,
        rowsNumber: this.total_records,
      };
    },
    /**
     * Table columns definition for full page
     */
    tableColumns(): UnifiedTableColumn[] {
      return [
        {
          name: 'test_scenario_name',
          label: this.$t('name'),
          field: 'test_scenario_name',
          align: 'left',
          sortable: false,
          style: 'width: 40%;',
          headerStyle: 'width: 40%; padding-left: 50px;',
        },
        {
          name: 'detail',
          label: this.$t('detail'),
          field: 'detail',
          align: 'left',
          sortable: false,
          style: 'width: 40%;',
          headerStyle: 'width: 40%;',
        },
      ];
    },
    /**
     * Simple columns for dashboard mode (q-table format)
     */
    dashboardColumns(): any[] {
      return [
        {
          name: 'test_scenario_name',
          label: this.$t('name'),
          field: 'test_scenario_name',
          align: 'left' as const,
        },
        {
          name: 'status',
          label: this.$t('status'),
          field: 'status',
          align: 'center' as const,
        },
      ];
    },
    /**
     * Table features configuration
     */
    tableFeatures(): Partial<TableFeatures> {
      return {
        sorting: false,
        selection: false,
        bulkActions: false,
        rowActions: true,
        pagination: true,
        resizable: false,
        columnReorder: false,
      };
    },
    /**
     * Row actions configuration
     */
    rowActions(): RowActionItem[] {
      return [
        {
          key: 'run_test',
          label: this.$t('run_test'),
          icon: 'play_circle',
        },
        {
          key: 'edit',
          label: this.$t('edit'),
          icon: 'edit',
        },
        {
          key: 'activate',
          label: this.$t('activate'),
          icon: 'check_circle',
          show: (row) => !row.enabled,
        },
        {
          key: 'deactivate',
          label: this.$t('deactivate'),
          icon: 'block',
          show: (row) => row.enabled,
        },
        {
          key: 'logs',
          label: this.$t('logs'),
          icon: 'account_tree',
        },
        {
          key: 'delete',
          label: this.$t('delete'),
          icon: 'delete',
          color: 'negative',
          separator: true,
        },
      ];
    },
  },
  setup() {
    return {
      debounceSearchInputFunc: null as any,
      request_params: ref<dynamicObj>({}),
      current_page: ref(1),
      total_pages: ref(1),
      page_size: ref(25),
      total_records: ref(0),
      workflowTestDialog: ref(false),
      testScenarioDetail: ref(false),
      testLogDialog: ref(false),
      selected: ref<string[]>([]),
      options: ref<any[]>([]),
      testProgressBanner: ref({
        visible: false,
        executed: 0,
        total: 0,
        currentTest: '',
        passedCount: 0,
      }),
    };
  },
});
</script>

<style lang="scss" scoped>
.pagination-section {
  margin-top: 20px;
  align-items: center;
  justify-content: center;
}

.clear-button {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  border-radius: 4px;
  border: 1px solid #d1d5db;
  cursor: pointer;
  transition:
    background-color 0.25s,
    border-color 0.25s;
  padding: 8px 12px 10px 8px;

  &:hover {
    background-color: #f3f4f6;
    border-color: #9ca3af;
  }
