<template>
  <q-card class="card">
    <q-toolbar class="text-white secondary-toolbar">
      <q-toolbar-title>
        <span class="text-weight-bold">{{
          isEditMode ? $t('edit_wfscenario') : $t('add_new_wfscenario')
        }}</span>
      </q-toolbar-title>
      <q-btn flat round dense icon="close" v-close-popup />
    </q-toolbar>
    <q-card-section class="row">
      <q-select
        v-model="workflowId"
        :label="workflowError || $t('select_workflow')"
        outlined
        dense
        class="col-12 card-padding q-mb-md"
        :options="workflowData"
        option-label="label"
        option-value="value"
        map-options
        emit-value
        :error="!!workflowError"
      />
      <q-input
        v-model="testScenarioName"
        :label="testScenarioNameError || $t('test_scenario_name')"
        outlined
        dense
        class="col-12 card-padding q-mb-md"
        :error="!!testScenarioNameError"
      />

      <div class="col-12 card-padding q-mb-md">
        <q-option-group
          v-model="inputType"
          :options="inputJsonOptions"
          color="primary"
          type="radio"
          inline
        />
      </div>

      <div class="col-12 card-padding q-mb-md">
        <template v-if="inputType === 'file'">
          <q-file
            class="select-field q-file-select-field"
            outlined
            multiple
            @update:model-value="handleUploadedFileChange"
            v-model="uploadedFiles"
            :label="$t('upload_extracted_workflow_test_scenario')"
            :error="hasJsonError"
            accept="application/json"
          >
            <template v-slot:prepend>
              <q-icon name="attachment" />
            </template>
            <template v-slot:file="{ index, file }">
              <div>{{ file.name }}</div>
              <q-tooltip>{{ file.name }}</q-tooltip>
              <span v-if="false">{{ index }}</span>
            </template>
          </q-file>
          <q-file
            class="select-field q-file-select-field mt-4"
            outlined
            multiple
            @update:model-value="handleExpectedFileChange"
            v-model="expectedDocumentFile"
            :label="$t('upload_actual_workflow_test_scenario')"
            :error="hasJsonError"
            accept="application/json"
          >
            <template v-slot:prepend>
              <q-icon name="attachment" />
            </template>
            <template v-slot:file="{ index, file }">
              <div>{{ file.name }}</div>
              <q-tooltip>{{ file.name }}</q-tooltip>
              <span v-if="false">{{ index }}</span>
            </template>
          </q-file>
        </template>
        <template v-else>
          <q-input
            class="col-12 card-padding q-mb-md json-textarea overflow-auto height-180px"
            autogrow
            filled
            dense
            outlined
            :label="$t('input_doc_json')"
            :error="hasJsonError"
            v-model="inputDocumentText"
            @input="validateJson"
            type="textarea"
          />
          <q-input
            class="col-12 card-padding q-mb-md json-textarea height-180px overflow-auto"
            autogrow
            filled
            dense
            outlined
            :label="hasJsonError ? jsonErrorMessage : $t('actual_doc_json')"
            :error="hasJsonError"
            :error-message="jsonErrorMessage"
            v-model="actualDocumentText"
            @input="validateJson"
            type="textarea"
          />
        </template>
      </div>
    </q-card-section>
    <q-card-actions align="right">
      <f-btn :label="$t('cancel')" appearance="cancel" v-close-popup />
      <f-btn
        class="q-mr-sm"
        :label="$t('send')"
        @click="submitWorkflowTestScenario"
      />
    </q-card-actions>
  </q-card>
</template>

<script lang="ts">
import { notify } from 'src/components/notifications/notify';
import { defineComponent, ref } from 'vue';
import helperMixin from 'src/mixins/helperMixin';
import { workflowTestApiService } from 'src/services';
import type { dynamicObj } from 'src/pages/assets';
import { ApiExceptions } from 'src/exceptions/index';
export default defineComponent({
  name: 'workflowNewTestScenario',
  mixins: [helperMixin],
  props: {
    workflowData: {
      type: Array,
      required: true,
    },
    testScenario: {
      type: Object,
      required: false,
      default: null,
    },
  },
  data() {
    return {
      dsubmit: false,
      isEditMode: false,
    };
  },
  mounted() {
    this.loadOptions();
    if (this.testScenario) {
      this.isEditMode = true;
      this.populateForm();
    }
  },
  emits: ['Close', 'reloadData'],
  methods: {
    async submitWorkflowTestScenario() {
      this.clearErrors();
      if (!this.isFormValid()) return;

      const formData = this.prepareFormData();
      if (!formData) return;

      await this.submitForm(formData);
    },

    clearErrors() {
      this.workflowError = '';
      this.testScenarioNameError = '';
      this.hasJsonError = false;
      this.jsonErrorMessage = '';
    },

    isFormValid() {
      this.workflowError = this.workflowId ? '' : this.$t('workflow_required');
      this.testScenarioNameError = this.testScenarioName
        ? ''
        : this.$t('test_scenario_name_required');

      return !!(this.workflowId && this.testScenarioName);
    },

    prepareFormData(): FormData | null {
      const formData = new FormData();

      if (this.inputType === 'file') {
        this.appendFileInputs(formData);
      } else {
        if (!this.appendTextInputs(formData)) {
          return null;
        }
      }

      return formData;
    },

    appendFileInputs(formData: FormData) {
      this.uploadedFiles.forEach((file) => {
        formData.append('input_document_json_file', file);
      });

      this.expectedDocumentFile.forEach((file) => {
        formData.append('actual_document_json_file', file);
      });
    },

    appendTextInputs(formData: FormData): boolean {
      if (this.inputDocumentText) {
        try {
          JSON.parse(this.inputDocumentText);
          formData.append('input_document_json_text', this.inputDocumentText);
        } catch (e) {
          this.setJsonError('invalid_input_json');
          return false;
        }
      }

      if (this.actualDocumentText) {
        try {
          JSON.parse(this.actualDocumentText);
          formData.append(
            'actual_document_json_text',
            this.actualDocumentText,
          );
        } catch (e) {
          this.setJsonError('invalid_actual_json');
          return false;
        }
      }

      return true;
    },

    setJsonError(key: string) {
      this.hasJsonError = true;
      this.jsonErrorMessage = this.$t(key);
    },

    async submitForm(formData: FormData) {
      formData.append('workflow_id', this.workflowId);
      formData.append('test_scenario_name', this.testScenarioName);

      try {
        let response;
        if (this.isEditMode && this.testScenario?.id) {
          response = await workflowTestApiService.editWorkflowTestScenario(
            this.testScenario.id,
            formData,
          );
        } else {
          response =
            await workflowTestApiService.newWorkflowTestScenario(formData);
        }

        if (!response.message) {
          throw response.error;
        }

        notify.success(response.message);
        this.resetForm();
        this.$emit('reloadData');
        this.$emit('Close', true);
      } catch (error) {
        const msg = ApiExceptions.getErrorMessage(error as dynamicObj);
        notify.error(msg);
        logError(error);
      }
    },

    handleUploadedFileChange(files: any) {
      this.uploadedFiles = files;
    },

    handleExpectedFileChange(files: any) {
      this.expectedDocumentFile = files;
    },

    resetForm() {
      this.workflowId = '';
      this.testScenarioName = '';
      this.inputType = 'file';
      this.uploadedFiles = [];
      this.expectedDocumentFile = [];
      this.inputDocumentText = '';
      this.actualDocumentText = '';
      this.hasJsonError = false;
      this.jsonErrorMessage = '';
    },

    validateJson() {
      try {
        JSON.parse(this.inputDocumentText);
        this.hasJsonError = false;
        this.jsonErrorMessage = '';
      } catch (e) {
        this.hasJsonError = true;
        this.jsonErrorMessage = this.$t('invalid_json');
        logError(e);
      }
    },

    populateForm() {
      if (this.testScenario) {
        this.workflowId = this.testScenario.workflow_id || '';
        this.testScenarioName = this.testScenario.test_scenario_name || '';

        if (this.testScenario.extracted_document_data) {
          this.inputType = 'text';
          this.inputDocumentText =
            typeof this.testScenario.extracted_document_data === 'string'
              ? this.testScenario.extracted_document_data
              : JSON.stringify(
                  this.testScenario.extracted_document_data,
                  null,
                  2,
                );
        }

        if (this.testScenario.actual_document_data) {
          this.inputType = 'text';
          this.actualDocumentText =
            typeof this.testScenario.actual_document_data === 'string'
              ? this.testScenario.actual_document_data
              : JSON.stringify(this.testScenario.actual_document_data, null, 2);
        }
      }
    },

    loadOptions() {
      this.inputJsonOptions = [
        { label: this.$t('upload_json_file'), value: 'file' },
        { label: this.$t('paste_raw_json'), value: 'text' },
      ];
    },
  },

  setup() {
    return {
      formData: {} as FormData,
      workflowId: ref(''),
      inputType: ref('file'),
      uploadedFiles: ref([]),
      expectedDocumentFile: ref([]),
      inputDocumentText: ref(''),
      actualDocumentText: ref(''),
      hasJsonError: ref(false),
      jsonErrorMessage: ref(''),
      workflowError: ref(''),
      testScenarioNameError: ref(''),
      testScenarioName: ref(''),
      inputJsonOptions: ref<any[]>([]),
    };
  },
});
</script>

<style lang="scss" scoped></style>
