import { allowed_file_type_json } from 'src/constants';
import {
  stripWorkflowListParams,
  type OutgoingQuery,
  type RouteQuery,
} from 'src/pages/WorkflowBuilder/workflowListUrlState';

export const WORKFLOW_LIST_TAB = 'workflowlist';

type TranslateFn = (key: string, params?: Record<string, unknown>) => string;

const defaultTranslate: TranslateFn = (key) => key;

/** The summary tab is the only one that loads the workflow list + charts. */
export function isSummaryTab(tab: string): boolean {
  return tab === 'workflowdashboard';
}

/**
 * Search, page, size and sort belong to the list tab, so switching to any other
 * tab drops them - in step with the column filters the list clears on leaving.
 */
export function queryForTab(
  currentQuery: RouteQuery,
  newTab: string,
): OutgoingQuery {
  if (newTab === WORKFLOW_LIST_TAB) {
    return { ...(currentQuery as OutgoingQuery), tab: newTab };
  }
  return { ...stripWorkflowListParams(currentQuery), tab: newTab };
}

export function calculateRate(
  summary: any,
  type: 'success' | 'failure',
): number {
  if (!summary?.total_logs) return 0;
  if (type === 'success') {
    const totalSuccess =
      (summary.total_success || 0) + (summary.total_failed_condition || 0);
    return Math.round((totalSuccess / summary.total_logs) * 100);
  }
  const actualFailures =
    (summary.total_error || 0) + (summary.total_no_data || 0);
  return Math.round((actualFailures / summary.total_logs) * 100);
}

export function getRateStatus(
  rate: number,
  translate: TranslateFn = defaultTranslate,
  isFailure = false,
): { color: string; badge: string } {
  if (isFailure) {
    if (rate <= 35)
      return { color: 'success', badge: translate('workflow_badge_healthy') };
    if (rate <= 65)
      return { color: 'warning', badge: translate('workflow_badge_warning') };
    return { color: 'danger', badge: translate('workflow_badge_critical') };
  }
  if (rate >= 65)
    return { color: 'success', badge: translate('workflow_badge_healthy') };
  if (rate >= 35)
    return { color: 'warning', badge: translate('workflow_badge_warning') };
  return { color: 'danger', badge: translate('workflow_badge_critical') };
}

export function getSuccessRateStatus(
  summary: any,
  translate: TranslateFn = defaultTranslate,
) {
  return getRateStatus(calculateRate(summary, 'success'), translate);
}

export function getFailureRateStatus(
  summary: any,
  translate: TranslateFn = defaultTranslate,
) {
  return getRateStatus(calculateRate(summary, 'failure'), translate, true);
}

export function getTotalRunsContext(
  filters: { dateRange?: { start?: string; end?: string } } = {},
  translate: TranslateFn = defaultTranslate,
): string {
  const start = filters?.dateRange?.start;
  const end = filters?.dateRange?.end;
  if (!start || !end) return translate('workflow_all_time');
  const startDate = new Date(start);
  const endDate = new Date(end);
  if (isNaN(startDate.getTime()) || isNaN(endDate.getTime())) {
    return translate('workflow_all_time');
  }
  const days = Math.ceil(
    (endDate.getTime() - startDate.getTime()) / (1000 * 60 * 60 * 24),
  );
  return translate('workflow_over_days', { days });
}

export function getDelta(
  currentValue: number,
  compareValue: number,
  compareMode: boolean | undefined,
  hasCompareSummary: boolean,
): number | null {
  if (!compareMode || !hasCompareSummary) return null;
  return currentValue - compareValue;
}

export function getSuccessRateDelta(
  summary: any,
  compareSummary: any,
  filters: { compareMode?: boolean },
) {
  return getDelta(
    calculateRate(summary, 'success'),
    calculateRate(compareSummary, 'success'),
    filters?.compareMode,
    !!compareSummary,
  );
}

export function getTotalRunsDelta(
  summary: any,
  compareSummary: any,
  filters: { compareMode?: boolean },
) {
  return getDelta(
    summary?.total_logs || 0,
    compareSummary?.total_logs || 0,
    filters?.compareMode,
    !!compareSummary,
  );
}

export function getTotalSuccessDelta(
  summary: any,
  compareSummary: any,
  filters: { compareMode?: boolean },
) {
  return getDelta(
    summary?.total_success || 0,
    compareSummary?.total_success || 0,
    filters?.compareMode,
    !!compareSummary,
  );
}

export function getFailureRateDelta(
  summary: any,
  compareSummary: any,
  filters: { compareMode?: boolean },
) {
  return getDelta(
    calculateRate(summary, 'failure'),
    calculateRate(compareSummary, 'failure'),
    filters?.compareMode,
    !!compareSummary,
  );
}

export function getWorkflowCreatedDelta(
  workflowsCreated: string | number | undefined,
  compareCreated: number | null | undefined,
  filters: { compareMode?: boolean },
) {
  if (!filters?.compareMode || compareCreated === null || compareCreated === undefined)
    return null;
  const current = parseInt(workflowsCreated as string, 10) || 0;
  return getDelta(current, compareCreated, true, true) ?? null;
}

/**
 * Returns the route path for viewing a workflow based on its type.
 */
export function getWorkflowDetailRoute(workflowId: string, workflowType?: string): string {
  if (workflowType === 'advanced') {
    return `/advanced_workflow_designer/${workflowId}`;
  }
  return `/workflow_designer/${workflowId}`;
}

export function hasAllowedFileType(file: { type: string; name: string }) {
  let isAllowed = allowed_file_type_json.includes(file.type);
  if (!isAllowed) {
    const ext = file.name.split('.').pop() || '';
    isAllowed = allowed_file_type_json.includes(ext);
  }
  return isAllowed;
}
