<template>
  <q-card class="q-pa-md">
    <div class="row-container">
      <div class="width-15-percent">
        <q-input
          outlined
          dense
          v-model="dates.main.start"
          :label="$t('start_date')"
          @click="popup.main.start = true"
        >
          <template v-slot:append>
            <q-icon name="event" class="cursor-pointer">
              <q-popup-proxy
                v-model="popup.main.start"
                cover
                transition-show="scale"
                transition-hide="scale"
              >
                <q-date
                  v-model="dates.main.start"
                  :mask="date_pattern"
                  @update:model-value="
                    onDateSelect('main', 'start', dates.main.start)
                  "
                  :options="startDateOptions('main')"
                />
              </q-popup-proxy>
            </q-icon>
          </template>
        </q-input>
      </div>
      <div class="width-15-percent">
        <q-input
          outlined
          dense
          v-model="dates.main.end"
          :label="$t('end_date')"
          @click="popup.main.end = true"
        >
          <template v-slot:append>
            <q-icon name="event" class="cursor-pointer">
              <q-popup-proxy
                v-model="popup.main.end"
                cover
                transition-show="scale"
                transition-hide="scale"
              >
                <q-date
                  v-model="dates.main.end"
                  :mask="date_pattern"
                  @update:model-value="
                    onDateSelect('main', 'end', dates.main.end)
                  "
                  :options="endDateOptions('main')"
                />
              </q-popup-proxy>
            </q-icon>
          </template>
        </q-input>
      </div>
      <div class="width-15-percent">
        <q-select
          outlined
          dense
          :options="availableWorkflows"
          v-model="selectedWorkflow"
          emit-value
          map-options
          :label="$t('workflow_name')"
          @update:model-value="onWorkflowChange"
        />
      </div>
      <div class="row-container action-buttons">
        <div class="clear-button" @click="clearFilters">
          <q-icon name="clear" size="xs" />
          <span>{{ $t('clear') }}</span>
        </div>
        <div class="compare-button">
          <q-checkbox
            dense
            v-model="compareMode"
            :label="$t('compare')"
            @update:model-value="onCompareModeChange"
          />
        </div>
      </div>
    </div>
    <q-separator v-if="compareMode" class="q-mt-md" />
    <div v-if="compareMode" class="comparison-hint q-mt-sm">
      {{ $t('workflow_comparison_period') }}
    </div>
    <div v-if="compareMode" class="q-mt-sm row-container">
      <div class="width-15-percent">
        <q-input
          outlined
          dense
          v-model="dates.compare.start"
          :label="$t('start_date')"
          @click="popup.compare.start = true"
        >
          <template v-slot:append>
            <q-icon name="event" class="cursor-pointer">
              <q-popup-proxy
                v-model="popup.compare.start"
                cover
                transition-show="scale"
                transition-hide="scale"
              >
                <q-date
                  v-model="dates.compare.start"
                  :mask="date_pattern"
                  @update:model-value="
                    onDateSelect('compare', 'start', dates.compare.start)
                  "
                  :options="startDateOptions('compare')"
                />
              </q-popup-proxy>
            </q-icon>
          </template>
        </q-input>
      </div>
      <div class="width-15-percent">
        <q-input
          outlined
          dense
          v-model="dates.compare.end"
          :label="$t('end_date')"
          @click="popup.compare.end = true"
        >
          <template v-slot:append>
            <q-icon name="event" class="cursor-pointer">
              <q-popup-proxy
                v-model="popup.compare.end"
                cover
                transition-show="scale"
                transition-hide="scale"
              >
                <q-date
                  v-model="dates.compare.end"
                  :mask="date_pattern"
                  @update:model-value="
                    onDateSelect('compare', 'end', dates.compare.end)
                  "
                  :options="endDateOptions('compare')"
                />
              </q-popup-proxy>
            </q-icon>
          </template>
        </q-input>
      </div>
    </div>
  </q-card>
</template>

<script lang="ts">
import { defineComponent, ref, nextTick, PropType } from 'vue';
import dateUtils from 'src/utils/date';
import cache from 'src/utils/cache';
import { CONSTANTS } from 'src/constants';
import type { dynamicObj } from 'src/pages/assets';

export interface FilterState {
  dateRange: { start: string; end: string };
  compareMode: boolean;
  compareDateRange: { start: string; end: string };
  selectedWorkflow: string;
  // May add more filters in future
  // statuses: string[];
  // custom: Record<string, string | number>;
}

export default defineComponent({
  name: 'WorkflowFilterBar',
  mixins: [dateUtils, cache],
  props: {
    availableWorkflows: {
      type: Array as PropType<{ label: string; value: string }[]>,
      default: () => [],
    },
  },
  setup() {
    const today = new Date().toISOString().split('T')[0];
    return {
      dates: ref({
        main: { start: '', end: '' },
        compare: { start: '', end: '' },
      } as any),
      popup: ref({
        main: { start: false, end: false },
        compare: { start: false, end: false },
      } as any),
      selectedWorkflow: ref(''),
      compareMode: ref(false),
      today,
      date_pattern: ref(''),
    };
  },
  mounted() {
    this.init();
  },
  computed: {
    // Reactive read of the date-format preference; it can arrive after mount.
    docDateFormat(): string {
      return this.getDocDateFormat();
    },
  },
  watch: {
    // The preference loaded after the initial render — re-init so the default
    // range shows in the user's format (init reads any persisted selection
    // back from localStorage, so nothing the user picked is lost).
    docDateFormat() {
      this.init();
    },
  },
  methods: {
    init() {
      this.date_pattern = this.getDatePattern();

      const saved_filter = this.getDataByKey(
        CONSTANTS.workflow_dashboard_filters,
      ) as dynamicObj;

      let start_date_universal = '';
      let end_date_universal = '';

      if (saved_filter && saved_filter.dates) {
        start_date_universal = this.formatDateToUniversal(saved_filter.dates.main.start);
        end_date_universal = this.formatDateToUniversal(saved_filter.dates.main.end);
      } else {
        end_date_universal = this.today;
        const monthAgoDate = new Date();
        monthAgoDate.setMonth(monthAgoDate.getMonth() - 1);
        start_date_universal = monthAgoDate.toISOString().split('T')[0];
      }

      this.dates.main.start = this.formatDateAccordingToPreference(
        start_date_universal,
        true,
        '',
      );
      this.dates.main.end = this.formatDateAccordingToPreference(
        end_date_universal,
        true,
        '',
      );

      this.compareMode = saved_filter ? saved_filter.compareMode : false;
      if (
        saved_filter &&
        saved_filter.compareMode &&
        saved_filter.dates.compare
      ) {
        const compare_start_universal = this.formatDateToUniversal(
          saved_filter.dates.compare.start,
        );
        const compare_end_universal = this.formatDateToUniversal(
          saved_filter.dates.compare.end,
        );
        this.dates.compare.start = this.formatDateAccordingToPreference(
          compare_start_universal,
          true,
          '',
        );
        this.dates.compare.end = this.formatDateAccordingToPreference(
          compare_end_universal,
          true,
          '',
        );
      }
      this.selectedWorkflow = saved_filter ? saved_filter.selectedWorkflow : '';

      this.updateFilters();
    },

    onDateSelect(group: string, field: string, val: string) {
      this.dates[group][field] = val;

      nextTick(() => {
        this.popup[group][field] = false;
      });

      this.setDataToLocalStorage(CONSTANTS.workflow_dashboard_filters, {
        dates: this.dates,
        selectedWorkflow: this.selectedWorkflow,
        compareMode: this.compareMode,
      });
      this.emitDateRangeChange(group);
    },

    onCompareModeChange(val: boolean) {
      this.compareMode = val;
      this.setDataToLocalStorage(CONSTANTS.workflow_dashboard_filters, {
        dates: this.dates,
        selectedWorkflow: this.selectedWorkflow,
        compareMode: this.compareMode,
      });
      this.emitCompareModeChange();
    },

    onWorkflowChange(val: string) {
      this.selectedWorkflow = val;
      this.setDataToLocalStorage(CONSTANTS.workflow_dashboard_filters, {
        dates: this.dates,
        selectedWorkflow: this.selectedWorkflow,
        compareMode: this.compareMode,
      });
      this.emitWorkflowChange();
    },

    clearFilters() {
      this.dates = {
        main: { start: '', end: '' },
        compare: { start: '', end: '' },
      };
      this.selectedWorkflow = '';
      this.compareMode = false;
      this.setDataToLocalStorage(CONSTANTS.workflow_dashboard_filters, {
        dates: this.dates,
        selectedWorkflow: this.selectedWorkflow,
        compareMode: this.compareMode,
      });
      this.emitClearFilters();
    },

    startDateOptions(_group: string) {
      return (val: string) => {
        const dateVal = this.formatDateToUniversal(val);
        if (!dateVal || dateVal === '-') {
          return true;
        }
        return dateVal <= this.today;
      };
    },

    endDateOptions(group: string) {
      return (val: string) => {
        const dateVal = this.formatDateToUniversal(val);
        if (!dateVal || dateVal === '-') {
          return true;
        }
        const start = this.dates[group].start;
        if (!start || start === '-') {
          return dateVal <= this.today;
        }
        return dateVal >= start && dateVal <= this.today;
      };
    },

    emitDateRangeChange(_group: string) {
      this.updateFilters();
    },

    emitWorkflowChange() {
      this.updateFilters();
    },

    emitCompareModeChange() {
      this.updateFilters();
    },

    updateFilters() {
      // Convert dates to YYYY-MM-DD format for API
      const updatedFilters: FilterState = {
        dateRange: {
          start: this.formatDateToUniversal(this.dates.main.start),
          end: this.formatDateToUniversal(this.dates.main.end),
        },
        compareMode: this.compareMode,
        compareDateRange: {
          start: this.formatDateToUniversal(this.dates.compare.start),
          end: this.formatDateToUniversal(this.dates.compare.end),
        },
        selectedWorkflow: this.selectedWorkflow,
      };
      this.$emit('update:filters', updatedFilters);
    },

    emitClearFilters() {
      this.$emit('update:filters', {
        dateRange: { start: '', end: '' },
        compareMode: false,
        compareDateRange: { start: '', end: '' },
        selectedWorkflow: '',
      });
      this.$emit('filters-cleared');
    },
  },
});
</script>

