<template>
  <span class="new-workflow-button">
    <f-btn
      icon="add"
      :label="$t('new_workflow')"
      @click="openCreateWorkflow"
    />

    <q-dialog v-model="workflowDialog" class="options-dialog">
      <q-card class="q-pa-md">
        <q-card-section class="q-card__section row items-center justify-end close-btn-section">
          <q-btn flat round dense icon="close" @click="workflowDialog = false" />
        </q-card-section>
        <q-card-section class="column items-center text-center header-contents">
          <div class="text-h6 options-dialog-title">{{ $t('create_new_workflow') }}</div>
          <p class="text-grey-7 options-dialog-info">{{ $t('create_new_workflow_info') }}</p>
        </q-card-section>
        <q-card-section>
          <div class="row options-container">
            <div class="col option">
              <q-card
                flat
                bordered
                class="q-pa-md text-center cursor-pointer workflow-type-card"
                @click="openDesigner('/workflow_designer')"
              >
                <div class="text-bold text-subtitle1 q-mb-sm option-title">{{ $t('standard_workflow') }}</div>
                <div class="workflow-icon-wrapper">
                  <StandardIcon class="q-mb-sm workflow-icon" />
                </div>
              </q-card>
            </div>

            <div class="col option">
              <q-card
                flat
                bordered
                class="q-pa-md text-center cursor-pointer workflow-type-card"
                @click="openDesigner('/advanced_workflow_designer')"
              >
                <div class="text-bold text-subtitle1 q-mb-sm option-title">{{ $t('advanced_workflow') }}</div>
                <div class="workflow-icon-wrapper">
                  <AdvancedIcon class="q-mb-sm workflow-icon" />
                </div>
              </q-card>
            </div>
          </div>
        </q-card-section>
      </q-card>
    </q-dialog>
  </span>
</template>

<script lang="ts">
import { defineComponent, ref, computed } from 'vue';
import { storeToRefs } from 'pinia';
import { useSettingStore } from 'src/store/main';
import { toBoolPreference } from 'src/utils/preferenceBool';
import { ADVANCED_WORKFLOW_SETTING_NAME } from 'src/pages/Settings/Components/Modules/workflowBuilderHelpers';
import StandardIcon from 'src/pages/WorkflowBuilder/WorkflowComponnets/StandardIcon.vue';
import AdvancedIcon from 'src/pages/WorkflowBuilder/WorkflowComponnets/AdvancedIcon.vue';

export default defineComponent({
  name: 'NewWorkflowButton',
  components: { StandardIcon, AdvancedIcon },

  methods: {
    openCreateWorkflow() {
      if (this.hasAdvancedWorkflow) {
        this.workflowDialog = true;
      } else {
        this.openDesigner('/workflow_designer');
      }
    },

    openDesigner(path: string) {
      this.workflowDialog = false;
      this.$router.push(path);
    },
  },

  setup() {
    const settingsStore = useSettingStore();
    const { user_settings } = storeToRefs(settingsStore);
    const hasAdvancedWorkflow = computed(() =>
      toBoolPreference(user_settings.value[ADVANCED_WORKFLOW_SETTING_NAME]),
    );

    return {
      hasAdvancedWorkflow,
      workflowDialog: ref(false),
    };
  },
});
</script>

