<template>
  <SubHeader
    name="page_workflow"
    :label="$t('workflowsdashboard')"
    :show_expiry_alert="true"
    :display_help_link="true"
  />

  <!-- No license state -->
  <div v-if="licenseChecked && !hasAnyLicense && !isAdmin" class="flex flex-center" style="height: calc(100vh - 100px)">
    <div class="text-center">
      <q-icon name="block" size="64px" color="grey-5" />
      <div class="text-h6 text-grey-7 q-mt-md">{{ $t('no_workflow_license') }}</div>
      <div class="text-caption text-grey-5 q-mt-sm">{{ $t('contact_admin_for_license') }}</div>
    </div>
  </div>

  <div v-else class="dashboard-container">
    <div class="row q-pa-md">
      <div class="col-md-5">
        <q-tabs
          v-model="tab"
          dense
          class="text-grey workflowDashboardTabs"
          active-color="primary"
          indicator-color="primary"
          align="left"
          narrow-indicator
        >
          <q-tab
            name="workflowdashboard"
            :label="$t('dashboard')"
            class="text-capitalize"
          />
          <q-tab
            name="workflowlist"
            :label="$t('workflow_list')"
            class="text-capitalize"
          />
          <q-tab
            name="workflowtestmanager"
            :label="$t('test_manager_list')"
            class="text-capitalize"
            @click="dashboard_tab_active = false"
          />
          <q-tab
            v-if="isAdmin"
            name="license"
            :label="$t('license')"
            class="text-capitalize"
          />
          <q-tab
            v-if="isAdmin"
            name="cardsdk"
            :label="$t('card_sdk')"
            class="text-capitalize"
          />
        </q-tabs>
      </div>
      <div class="col-md-1"></div>
      <div class="col-md-6 display-flex no-wrap justify-end">
        <NewWorkflowButton class="mr-6" />
        <f-btn
          icon="account_tree"
          appearance="outline"
          :label="$t('wf_workflow_templates')"
          class="mr-6"
          @click="ShowTemplateDashboard = true"
        />
        <f-btn
          icon="file_upload"
          appearance="outline"
          :label="$t('import_workflow')"
          @click="
            multiUploaderDialog = true;
            uploadedFiles = null;
          "
        />
      </div>
    </div>

    <q-separator />

    <q-tab-panels v-model="tab" animated>
      <q-tab-panel name="workflowdashboard">
        <!-- Filter Bar -->
        <WorkflowFilterBar
          v-model:filters="filters"
          :available-workflows="workflowOptions"
          class="q-mb-md"
        />

        <!-- KPI Cards -->
        <div class="row q-col-gutter-md q-mb-md">
          <div class="col-12 col-md-2 col-sm-6">
            <WorkflowKpiCard
              :title="$t('workflow_executed_today')"
              :value="worflowDashboardSummary?.executed_today || 0"
              :loading="loading"
            />
          </div>
          <div class="col-12 col-md-2 col-sm-6">
            <WorkflowKpiCard
              :title="$t('workflow_created')"
              :value="workflowsCreated || 0"
              :show-comparison="filters.compareMode"
              :compare-value="compareData.created || 0"
              :delta="getWorkflowCreatedDelta() as number"
              :loading="loading"
            />
          </div>
          <div class="col-12 col-md-2 col-sm-6">
            <WorkflowKpiCard
              :title="$t('total_runs')"
              :subtitle="getTotalRunsContext()"
              :value="worflowDashboardSummary?.total_logs || 0"
              :show-comparison="filters.compareMode"
              :compare-value="compareData.summary?.total_logs || 0"
              :delta="getTotalRunsDelta() as number"
              :loading="loading"
            />
          </div>
          <div class="col-12 col-md-2 col-sm-6">
            <WorkflowKpiCard
              :title="$t('total_success')"
              :subtitle="
                $t('workflow_subtitle_total_runs', {
                  count: worflowDashboardSummary?.total_logs || 0,
                })
              "
              :value="worflowDashboardSummary?.total_success || 0"
              :progress-value="
                calculateRate(worflowDashboardSummary, 'success')
              "
              :progress-label="
                $t('workflow_success_rate_percentage', {
                  rate: calculateRate(worflowDashboardSummary, 'success'),
                })
              "
              :show-comparison="filters.compareMode"
              :compare-value="compareData.summary?.total_success || 0"
              :delta="getTotalSuccessDelta() as number"
              :loading="loading"
            />
          </div>
          <div class="col-12 col-md-2 col-sm-6">
            <WorkflowKpiCard
              :title="$t('success_rate')"
              :subtitle="
                $t('workflow_subtitle_based_on_runs', {
                  count: worflowDashboardSummary?.total_logs || 0,
                })
              "
              :value="calculateRate(worflowDashboardSummary, 'success') + '%'"
              :show-comparison="filters.compareMode"
              :compare-value="
                calculateRate(compareData.summary, 'success') + '%'
              "
              :badge="getSuccessRateStatus().badge"
              :status-color="getSuccessRateStatus().color as any"
              :delta="getSuccessRateDelta() as number"
              :loading="loading"
            />
          </div>
          <div class="col-12 col-md-2 col-sm-6">
            <WorkflowKpiCard
              :title="$t('fails_rate')"
              :subtitle="
                $t('workflow_subtitle_based_on_runs', {
                  count: worflowDashboardSummary?.total_logs || 0,
                })
              "
              :show-comparison="filters.compareMode"
              :compare-value="
                calculateRate(compareData.summary, 'failure') + '%'
              "
              :value="calculateRate(worflowDashboardSummary, 'failure') + '%'"
              :badge="getFailureRateStatus().badge"
              :status-color="getFailureRateStatus().color as any"
              :delta="getFailureRateDelta() as number"
              :loading="loading"
            />
          </div>
        </div>

        <!-- Charts & Activity -->
        <div class="row q-col-gutter-md">
          <div class="col-12 col-md-7">
            <WorkflowLineChart
              :workflowCardSummary="worflowDashboardSummary"
              :loading="loading"
            />
          </div>
          <div class="col-12 col-md-5">
            <q-card class="recent-activity-card q-pa-md">
              <q-card-section class="q-pa-md">
                <div class="cards-title font-size-21 q-mb-md mb-25">
                  {{ $t('recent_activity') }}
                </div>
                <q-tabs
                  v-model="activityTab"
                  dense
                  class="text-grey"
                  active-color="primary"
                  indicator-color="primary"
                  align="left"
                  narrow-indicator
                >
                  <q-tab
                    name="runs"
                    :label="$t('latest_workflow_tests')"
                    class="text-capitalize"
                  />
                  <q-tab
                    name="workflows"
                    :label="$t('latest_workflows')"
                    class="text-capitalize"
                  />
                </q-tabs>
                <q-separator class="q-my-md" />
                <q-tab-panels v-model="activityTab" animated>
                  <q-tab-panel name="runs" class="q-pa-none">
                    <workflowTestManager
                      :workflowdashboardActive="dashboard_tab_active = true"
                    />
                    <q-btn
                      dense
                      flat
                      color="primary"
                      size="md"
                      class="text-lowercase q-mt-sm"
                      :title="$t('load_more') + '...'"
                      :label="$t('more') + '...'"
                      @click="tab = 'workflowtestmanager'"
                    />
                  </q-tab-panel>
                  <q-tab-panel name="workflows" class="q-pa-none">
                    <DocBitsTable
                      :rows="rowsDataWorkflow"
                      :columns="columnsNamesWF"
                      row-key="name"
                      table-id="wf_dashboard_workflows_table"
                      dense
                      :features="{
                        sorting: false,
                        filtering: false,
                        selection: false,
                        bulkActions: false,
                        rowActions: true,
                        resizable: false,
                        pagination: false,
                        columnReorder: false,
                        stickyLastColumn: true,
                      }"
                      :row-actions="wfRowActions"
                      no-data-label="no_record_found"
                      flat-style
                      @row-action="handleWfRowAction"
                    >
                      <template #body-cell-enabled="{ row }">
                        <q-badge
                          v-if="row.enabled"
                          color="green"
                          text-color="white"
                          :label="$t('active')"
                          size="md"
                          class="q-pa-sm"
                        />
                        <q-badge
                          v-else
                          color="grey"
                          text-color="white"
                          :label="$t('inactive')"
                          size="md"
                          class="q-pa-sm"
                        />
                      </template>
                      <template #body-cell-workflow_type="{ row }">
                        <q-badge
                          :color="row.workflow_type === 'advanced' ? 'mission' : 'blue-grey'"
                          text-color="white"
                          :label="row.workflow_type === 'advanced' ? $t('advanced_workflow') : $t('standard')"
                          size="md"
                          class="q-pa-xs"
                        />
                      </template>
                    </DocBitsTable>
                    <q-btn
                      dense
                      flat
                      color="primary"
                      size="md"
                      class="text-lowercase q-mt-sm"
                      :title="$t('load_more') + '...'"
                      :label="$t('more') + '...'"
                      @click="tab = 'workflowlist'"
                    />
                  </q-tab-panel>
                </q-tab-panels>
              </q-card-section>
            </q-card>
          </div>
        </div>
      </q-tab-panel>

      <q-tab-panel name="workflowlist">
        <workflow :key="workflowListKey" />
      </q-tab-panel>
      <q-tab-panel name="workflowtestmanager">
        <workflowTestManager :workflowdashboardActive="false" />
      </q-tab-panel>
      <q-tab-panel v-if="isAdmin" name="license">
        <WorkflowLicense />
      </q-tab-panel>
      <q-tab-panel v-if="isAdmin" name="cardsdk">
        <CardSDK />
      </q-tab-panel>
    </q-tab-panels>
  </div>

  <!-- MultiUploader Dialog -->
  <q-dialog v-model="multiUploaderDialog">
    <q-card class="vw-50">
      <q-toolbar class="text-white secondary-toolbar">
        <q-toolbar-title>
          <span class="text-weight-bold">{{ $t('upload_workflow') }}</span>
        </q-toolbar-title>
        <q-btn flat round dense icon="close" v-close-popup />
      </q-toolbar>
      <q-card-section>
        <div
          class="drag-area text-center full-width p-4"
          id="box-droppable"
          @drop="drop"
          @dragover="allowDrop"
          @dragleave="dragLeave"
        >
          <Icon icon="mdi:export" width="64" height="64" />
          <div class="p-20">{{ $t('land_dragndrop') }}</div>
          <q-file
            outlined
            multiple
            class="select-field multi-upload"
            v-model="uploadedFiles"
            @update:model-value="uploadFile"
            :label="$t('upload_workflow')"
            accept="application/json"
          >
            <template v-slot:prepend>
              <q-icon name="attachment" />
            </template>
            <template v-slot:file="{ file }">
              <div class="text-white">{{ file.name }}</div>
            </template>
          </q-file>
        </div>
      </q-card-section>
    </q-card>
  </q-dialog>

  <q-dialog
    v-model="ShowTemplateDashboard"
    @keypress.esc="ShowTemplateDashboard = false"
  >
    <workflowTemplates />
  </q-dialog>
</template>

<script lang="ts">
import { notify } from 'src/components/notifications/notify';

import { storeToRefs } from 'pinia';
import { defineComponent, ref } from 'vue';
import { debounce } from 'quasar';
import { useRoute } from 'vue-router';
import workflow from 'src/pages/WorkflowBuilder/workflow.vue';
import helperUtil from 'src/utils/helperUtil';
import helperMixin from 'src/mixins/helperMixin';
import type { dynamicObj } from 'src/pages/assets';
import { ApiExceptions } from 'src/exceptions';
import { workflowApiService } from 'src/services';
import { allowed_file_type_json } from 'src/constants';
import WorkflowLineChart from 'src/pages/WorkflowBuilder/WorkflowLineChart.vue';
import SubHeader from 'src/pages/Settings/Components/Sub-Header.vue';
import workflowTemplates from 'src/pages/WorkflowBuilder/workflow_templates_view.vue';
import NewWorkflowButton from 'src/pages/WorkflowBuilder/WorkflowComponnets/NewWorkflowButton.vue';
import workflowTestManager from 'src/pages/WorkflowBuilder/WorkflowTestManager/workflowTestManager.vue';
import WorkflowLicense from 'src/pages/WorkflowBuilder/WorkflowLicense.vue';
import CardSDK from 'src/pages/WorkflowBuilder/CardSDK.vue';
import { isOrganisationAdmin } from 'src/utils/UserDetails';
import WorkflowKpiCard from 'src/pages/WorkflowBuilder/components/WorkflowKpiCard.vue';
import WorkflowFilterBar from 'src/pages/WorkflowBuilder/components/WorkflowFilterBar.vue';
import { useWorkflowLogsVariablesStore } from 'src/store/WorkflowBuilder/workflow_logs_variables.store';
import DocBitsTable from 'src/components/Table/DocBitsTable.vue';
import type { RowActionItem } from 'src/components/Table/types/table/unified-table';
import {
  getWorkflowDetailRoute,
  isSummaryTab,
  queryForTab,
} from 'src/pages/WorkflowBuilder/workflowDashboardLogic';

export default defineComponent({
  name: 'wfDashboard',
  mixins: [helperUtil, helperMixin],
  components: {
    SubHeader,
    workflow,
    workflowTestManager,
    WorkflowLineChart,
    workflowTemplates,
    NewWorkflowButton,
    WorkflowKpiCard,
    WorkflowFilterBar,
    WorkflowLicense,
    CardSDK,
    DocBitsTable,
  },

  async mounted() {
    document.addEventListener(
      'workflow_status_changed',
      this.handleWorkflowStatusChange,
    );

    await this.checkLicenseStatus();
    if (!this.hasAnyLicense && this.isAdmin) {
      this.tab = 'license';
    }
    // Summary tab only — other tabs load their own list (avoids a duplicate
    // /v3/workflow/dashboard hit).
    if (isSummaryTab(this.tab)) {
      this.getWorkflowList();
    }

    if (this.$route.query.tab !== this.tab) {
      this.$router.replace({ query: { ...this.$route.query, tab: this.tab } }).catch(() => {});
    }
  },

  unmounted() {
    document.removeEventListener(
      'workflow_status_changed',
      this.handleWorkflowStatusChange,
    );
  },

  watch: {
    tab: {
      handler(newTab: string, oldTab: string) {
        sessionStorage.setItem('workflow_active_tab', newTab);
        
        if (this.$route.query.tab !== newTab) {
          this.$router
            .replace({ query: queryForTab(this.$route.query, newTab) })
            .catch(() => {});
        }

        // When switching to workflowdashboard tab, only fetch if data is missing.
        // If WorkflowFilterBar remounts it will emit filters, which triggers the
        // filters watcher — no need to also call here and risk a duplicate in-flight request.
        if (isSummaryTab(newTab) && oldTab && !isSummaryTab(oldTab)) {
          this.$nextTick(() => {
            // First open of the summary tab — load the list it was skipped on mount.
            if (!this.workflowListLoaded) {
              this.getWorkflowList();
            }
            if (
              !this.worflowDashboardSummary &&
              this.filters.dateRange.start &&
              this.filters.dateRange.end
            ) {
              this.applyDateFilter();
            }
          });
        }
      },
    },
    filters: {
      deep: true,
      handler: function () {
        this.debouncedFiltersHandler();
      },
    },
  },

  methods: {
    async checkLicenseStatus() {
      try {
        const res = await workflowApiService.getLicenseStatus();
        if (res.data?.success) {
          this.hasAnyLicense = res.data.workflow || res.data.advanced_workflow;
        }
      } catch {
        // If license check fails, allow access (fail open)
        this.hasAnyLicense = true;
      } finally {
        this.licenseChecked = true;
      }
    },

    handleWfRowAction(payload: { action: string; row: any }) {
      if (payload.action === 'view') {
        this.viewWorkflowDetail(payload.row.id, payload.row.workflow_type);
      }
    },
    viewWorkflowDetail(workflowId: string, workflowType?: string) {
      this.$router.push(getWorkflowDetailRoute(workflowId, workflowType));
    },

    calculateRate(summary: any, type: 'success' | 'failure'): number {
      if (!summary?.total_logs) return 0;
      if (type === 'success') {
        // Success includes: total_success + total_failed_condition (workflow executed correctly)
        const totalSuccess =
          (summary.total_success || 0) + (summary.total_failed_condition || 0);
        return Math.round((totalSuccess / summary.total_logs) * 100);
      }
      // Actual failures are only: total_error + total_no_data
      const actualFailures =
        (summary.total_error || 0) + (summary.total_no_data || 0);
      return Math.round((actualFailures / summary.total_logs) * 100);
    },

    getRateStatus(rate: number, isFailure = false) {
      if (isFailure) {
        if (rate <= 35)
          return { color: 'success', badge: this.$t('workflow_badge_healthy') };
        if (rate <= 65)
          return { color: 'warning', badge: this.$t('workflow_badge_warning') };
        return { color: 'danger', badge: this.$t('workflow_badge_critical') };
      }
      if (rate >= 65)
        return { color: 'success', badge: this.$t('workflow_badge_healthy') };
      if (rate >= 35)
        return { color: 'warning', badge: this.$t('workflow_badge_warning') };
      return { color: 'danger', badge: this.$t('workflow_badge_critical') };
    },

    getSuccessRateStatus() {
      return this.getRateStatus(
        this.calculateRate(this.worflowDashboardSummary, 'success'),
      );
    },

    getFailureRateStatus() {
      return this.getRateStatus(
        this.calculateRate(this.worflowDashboardSummary, 'failure'),
        true,
      );
    },

    getTotalRunsContext(): string {
      if (!this.filters.dateRange?.start || !this.filters.dateRange?.end) {
        return this.$t('workflow_all_time');
      }
      const start = new Date(this.filters.dateRange.start);
      const end = new Date(this.filters.dateRange.end);
      if (isNaN(start.getTime()) || isNaN(end.getTime())) {
        return this.$t('workflow_all_time');
      }
      const days = Math.ceil(
        (end.getTime() - start.getTime()) / (1000 * 60 * 60 * 24),
      );
      return this.$t('workflow_over_days', { days });
    },

    getDelta(currentValue: number, compareValue: number): number | null {
      if (!this.filters.compareMode || !this.compareData.summary) return null;
      return currentValue - compareValue;
    },

    getSuccessRateDelta(): number | null {
      return this.getDelta(
        this.calculateRate(this.worflowDashboardSummary, 'success'),
        this.calculateRate(this.compareData.summary, 'success'),
      );
    },

    getTotalRunsDelta(): number | null {
      return this.getDelta(
        this.worflowDashboardSummary?.total_logs || 0,
        this.compareData.summary?.total_logs || 0,
      );
    },

    getTotalSuccessDelta(): number | null {
      return this.getDelta(
        this.worflowDashboardSummary?.total_success || 0,
        this.compareData.summary?.total_success || 0,
      );
    },

    getFailureRateDelta(): number | null {
      return this.getDelta(
        this.calculateRate(this.worflowDashboardSummary, 'failure'),
        this.calculateRate(this.compareData.summary, 'failure'),
      );
    },

    getWorkflowCreatedDelta(): number | null {
      if (!this.filters.compareMode || this.compareData.created === null)
        return null;
      return this.getDelta(
        parseInt(this.workflowsCreated as string) || 0,
        this.compareData.created || 0,
      );
    },

    handleWorkflowStatusChange(event: Event) {
      const { workflowId, enabled } = (event as CustomEvent).detail;
      const workflow = (this.rowsDataWorkflow as any[]).find(
        (w) => w.id === workflowId,
      );
      if (workflow) workflow.enabled = enabled;
    },

    async getWorkflowList() {
      try {
        this.request_params = { order_by: 'last_modified_on' } as dynamicObj;
        if (this.searchQuery.length > 1)
          this.request_params['name'] = this.searchQuery;

        const response = await workflowApiService.getWorkflowDashboard(
          this.request_params,
        );
        if (response?.entries) {
          this.rowsDataWorkflow = response.entries.map((entry: any) => ({
            id: entry.id,
            name: entry.name,
            enabled: entry.enabled,
            workflow_type: entry.workflow_type || 'standard',
            last_modified_on: new Date(entry.last_modified_on).toLocaleString(),
            actions: '',
          }));

          this.workflowOptions = [
            { label: this.$t('all_workflows'), value: '' },
            ...response.entries.map((entry: any) => ({
              label: entry.name,
              value: entry.id,
            })),
          ];
        }
        // set only on success (empty org included) so we don't refetch every
        // visit; a failed fetch leaves it false to retry
        this.workflowListLoaded = true;
      } catch (err) {
        notify.error(err);
      }
    },

    async getWorkflowDashboardSummary(workflowId: string = '') {
      try {
        const params: any = {
          compare_mode: this.filters.compareMode,
          include_today: true,
        };

        if (workflowId) {
          params.workflow_id = workflowId;
        }

        if (this.filters.dateRange?.start && this.filters.dateRange?.end
          && this.filters.dateRange.start !== '-' && this.filters.dateRange.end !== '-') {
          params.main = {
            start_date: this.filters.dateRange.start,
            end_date: this.filters.dateRange.end,
          };
        }

        if (
          this.filters.compareMode &&
          this.compareDateRange.start &&
          this.compareDateRange.end
        ) {
          params.compare = {
            start_date: this.compareDateRange.start,
            end_date: this.compareDateRange.end,
          };
        }

        const response =
          await workflowApiService.getWorkflowDashboardSummary(params);

        if (response.success) {
          const mainSummary = response.main_summary || {};
          this.worflowDashboardSummary = {
            executed_today: response.executed_today || 0,
            total_logs: mainSummary.total_by_filter || 0,
            total_success: mainSummary.total_success || 0,
            total_failed_condition: mainSummary.total_failed_condition || 0,
            total_error: mainSummary.total_error || 0,
            total_no_data: mainSummary.total_no_data || 0,
            logs_by_count_filter: mainSummary.logs_by_count_filter || [],
          };

          if (this.filters.compareMode && response.compare_summary) {
            this.compareData.summary = {
              total_logs: response.compare_summary.total_by_filter || 0,
              total_success: response.compare_summary.total_success || 0,
              total_failed_condition:
                response.compare_summary.total_failed_condition || 0,
              total_error: response.compare_summary.total_error || 0,
              total_no_data: response.compare_summary.total_no_data || 0,
            };
          } else {
            this.compareData.summary = null;
          }
        }
      } catch (err) {
        logError('[getWorkflowDashboardSummary]', err);
        notify.error(err);
      }
    },

    async getWorkflowCreationSummary() {
      try {
        const params: any = {
          count_for: 'total',
          compare_mode: this.filters.compareMode,
        };

        if (this.filters.dateRange?.start && this.filters.dateRange?.end
          && this.filters.dateRange.start !== '-' && this.filters.dateRange.end !== '-') {
          params.start_date = this.filters.dateRange.start;
          params.end_date = this.filters.dateRange.end;
        }

        if (
          this.filters.compareMode &&
          this.compareDateRange.start &&
          this.compareDateRange.end
        ) {
          params.compare_start_date = this.compareDateRange.start;
          params.compare_end_date = this.compareDateRange.end;
        }

        const response =
          await workflowApiService.getWorkflowCreationSummary(params);
        if (response.success) {
          this.workflowsCreated = response.count || 0;

          if (
            this.filters.compareMode &&
            response.compare_count !== undefined
          ) {
            this.compareData.created = response.compare_count;
          } else {
            this.compareData.created = null;
          }
        }
      } catch (err) {
        logError('[getWorkflowCreationSummary]', err);
        notify.error(err);
      }
    },

    async applyDateFilter() {
      if (this.isLoadingData) {
        return;
      }

      this.isLoadingData = true;
      this.loading = true;

      try {
        const workflowId = this.filters.selectedWorkflow;

        if (isSummaryTab(this.tab)) {
          // independent summaries — load concurrently (each handles its own errors)
          await Promise.all([
            this.getWorkflowDashboardSummary(workflowId),
            this.getWorkflowCreationSummary(),
          ]);
        }
      } catch (err: unknown) {
        logError('[applyDateFilter]', err);
        const msg = ApiExceptions.getErrorMessage(err as dynamicObj);
        notify.error(msg);
      } finally {
        this.loading = false;
        this.isLoadingData = false;
      }
    },

    uploadFile(value: any) {
      this.uploadedFiles = value;
      if (!value)
        return notify.error(this.$t('NO_FILE_SELECTED'));
      this.uploadFiles(value);
    },

    allowDrop(event: any) {
      event.preventDefault();
      event.currentTarget.classList.add('bg-grey-5', 'bd-shadow');
    },

    drop(event: any) {
      event.preventDefault();
      event.currentTarget.classList.remove('bg-grey-5', 'bd-shadow');
      this.uploadFiles(event.dataTransfer.files);
    },

    dragLeave(event: any) {
      event.currentTarget.classList.remove('bg-grey-5', 'bd-shadow');
    },

    async uploadFiles(files: any) {
      try {
        this.multiUploaderDialog = false;
        this.uploadedFiles = null;

        if (files?.length > 10)
          return notify.error(this.$t('max_workflow_upload_limit'));

        this.formData = new FormData();
        let invalidCounter = 0;

        for (const file of files) {
          if (this.hasAllowedFileType(file))
            this.formData.append('workflow_json', file);
          else invalidCounter++;
        }

        if (invalidCounter > 0)
          return notify.error(this.$t('INVALID_FILES'));
        await this.uploadWorkflowJson(this.formData);
      } catch (err: any) {
        const msg = ApiExceptions.getErrorMessage(err as dynamicObj);
        notify.error(msg);
        logError(err);
      } finally {
        document.dispatchEvent(new CustomEvent('table_data_updated'));
      }
    },

    hasAllowedFileType(file: any) {
      let isAllowed = allowed_file_type_json.includes(file.type);
      if (!isAllowed) {
        const ext = file.name.split('.').pop();
        isAllowed = allowed_file_type_json.includes(ext);
      }
      return isAllowed;
    },

    async uploadWorkflowJson(formData: FormData) {
      try {
        const response = await workflowApiService.importWorkflowJson(formData);
        if (response.success === false) {
          logError(response);
          notify.error(this.$t('DOC_UPLOAD_ERROR'));
          notify.error(response.message);
        } else {
          this.workflowListKey++;
          this.tab = 'workflowlist';
        }
      } catch (err: any) {
        const msg = ApiExceptions.getErrorMessage(err as dynamicObj);
        notify.error(msg);
        logError(err);
      }
    },
  },

  setup() {
    const workflowVariableStore = useWorkflowLogsVariablesStore();
    const { dashboard_tab_active } = storeToRefs(workflowVariableStore); // optional

    const columnsNamesWF = ref([
      { name: 'name', label: 'Name', field: 'name', align: 'left' as const },
      { name: 'enabled', label: 'Status', field: 'enabled', align: 'center' as const },
      { name: 'workflow_type', label: 'Type', field: 'workflow_type', align: 'center' as const },
      { name: 'last_modified_on', label: 'Created On', field: 'last_modified_on', align: 'center' as const },
    ]);

    const filters = ref({
      dateRange: { start: '', end: '' },
      compareMode: false,
      compareDateRange: { start: '', end: '' },
      selectedWorkflow: '',
    });

    const activityTab = ref('runs');
    const compareData = ref({
      summary: null as any,
      created: null as number | null,
      isLoading: false,
    });
    const compareDateRange = ref({ start: '', end: '' });
    const isLoadingData = ref(false);

    const route = useRoute();
    const validWfTabs = ['workflowdashboard', 'workflowlist', 'workflowtestmanager', 'license', 'cardsdk'];
    // DOCB-6376: the workflow page opens on the List tab by default; an
    // explicit ?tab= query param or the session's last-used tab still wins.
    let initialTab = 'workflowlist';

    // Priority 1: URL query param (?tab=workflowlist)
    const urlTab = route.query.tab as string;
    if (urlTab && validWfTabs.includes(urlTab)) {
      initialTab = urlTab;
    }
    // Priority 2: Session storage (whether reload or not)
    else {
      const savedTab = sessionStorage.getItem('workflow_active_tab');
      if (savedTab && validWfTabs.includes(savedTab)) {
        initialTab = savedTab;
      }
    } // end of else (no URL tab param)

    const isAdmin = isOrganisationAdmin();
    const licenseChecked = ref(false);
    const hasAnyLicense = ref(true);

    // Debounce filter handler so rapid sequential emissions (e.g. FilterBar init
    // setting multiple fields) collapse into a single applyDateFilter() call.
    const debouncedFiltersHandler = debounce(function (this: any) {
      // summary charts are summary-tab only
      if (!isSummaryTab(this.tab)) {
        return;
      }
      if (this.filters.compareDateRange) {
        this.compareDateRange = this.filters.compareDateRange;
      }
      if (this.filters.dateRange.start && this.filters.dateRange.end) {
        this.applyDateFilter();
      }
    }, 150);

    return {
      isAdmin,
      licenseChecked,
      hasAnyLicense,
      dashboard_tab_active,
      debouncedFiltersHandler,
      request_params: ref({} as dynamicObj),
      columnsNamesWF,
      wfRowActions: [
        { key: 'view', label: 'view_detail', icon: 'visibility' },
      ] as RowActionItem[],
      workflowsCreated: ref<string | number>(''),
      rowsDataWorkflow: ref([]),
      tab: ref(initialTab),
      searchQuery: ref(''),
      workflowOptions: ref([] as any[]),
      worflowDashboardSummary: ref(null as any),
      ShowTemplateDashboard: ref(false),
      multiUploaderDialog: ref(false),
      uploadedFiles: ref(null),
      workflowListKey: ref(0),
      workflowListLoaded: ref(false),
      formData: {} as FormData,
      filters,
      activityTab,
      compareData,
      compareDateRange,
      loading: ref(false),
      isLoadingData,
    };
  },
});
</script>

