<template>
  <!-- <SubHeader name="page_workflow" :label="$t('my_workflows')" :show_expiry_alert="true" :display_help_link="true">
  </SubHeader> -->
<div class="row workflow-page">

  <div class="col-12 q-pb-md search-section">
    <div class="row">
      <div class="col-sm-8 col-md-6 col-lg-4 ">
        <q-input v-model="searchBy" dense :class="searchBy.length === 0 ? 'search-in-active' : 'search-active'"
          autofocus :placeholder="$t('search_workflow')" outlined maxlength="120"
          @update:model-value="inputValueChanges()">
          <template v-slot:append>
            <q-icon flat dense name="search" size="24px" color="primary" />
          </template>
        </q-input>
      </div>
      </div>
    </div>

  <DocBitsTable
    class="col-12"
      :rows="tableData"
      :columns="tableColumns"
      :features="tableFeatures"
      :row-actions="rowActions"
      :pagination="tablePagination"
      :rows-per-page-options="pageSizeOptions"
      :loading="isLoading"
      row-key="id"
      :table-id="tableId"
      @row-click="handleRowClick"
      @row-action="handleRowAction"
      @update:pagination="handlePaginationChange"
      @update:sorting="handleSortChange"
      @update:filters="handleColumnFiltersChange"
      paginationLabel="wf_pagination_size"
    >
      <!-- Bulk Actions Menu in header checkbox column -->
      <template #header-actions="{ selectedCount, selectedRows }">
        <BulkActionsMenu
          :actions="bulkActions"
          :selected-count="selectedCount"
          :selected-rows="Array.from(selectedRows).map(id => tableData.find(r => r.id === id)).filter(Boolean)"
          :disabled="selectedCount === 0"
          @action="handleBulkAction($event, Array.from(selectedRows))"
        />
      </template>

      <!-- Custom name column with enabled/disabled icon -->
      <template #body-cell-name="{ row }">
        <q-icon v-if="row.enabled" class="q-mr-sm" name="toggle_on" color="positive" size="24px" />
        <q-icon v-else class="q-mr-sm" name="toggle_off" color="grey-5" size="24px" />
        <span class="font-size-16" :class="row.enabled ? 'color-primary' : 'disabled-name'">
          {{ row.name }}
        </span>
      </template>

      <!-- Custom workflow_type column -->
      <template #body-cell-workflow_type="{ row }">
        <q-badge
          :color="row.workflow_type === 'advanced' ? 'mission' : 'blue-grey'"
          text-color="white"
          :label="row.workflow_type === 'advanced' ? $t('advanced_workflow') : $t('standard')"
          class="q-pa-xs"
        />
      </template>

      <template #body-cell-sort_order="{ row }">
        <span>
          {{ row.sort_order }}
          <q-tooltip
            anchor="top middle"
            self="bottom middle"
            class="execution-order-tooltip"
          >
            {{ $t('workflow_execution_order_tooltip') }}
          </q-tooltip>
        </span>
      </template>

      <!-- Custom when_condition column -->
      <template #body-cell-when_condition="{ row }">
        <span v-if="row.when_condition">{{ formatCard(row.when_condition) }}</span>
        <span v-else>-</span>
      </template>

      <!-- Custom created_on column with date formatting -->
      <template #body-cell-created_on="{ row }">
        <span v-if="row.created_on">{{ formatDateAccordingToPreference(row.created_on) }}</span>
        <span v-else>-</span>
      </template>

      <!-- Custom last_modified_on column with date formatting -->
      <template #body-cell-last_modified_on="{ row }">
        <span v-if="row.last_modified_on">{{ formatDateAccordingToPreference(row.last_modified_on) }}</span>
        <span v-else>-</span>
      </template>
  </DocBitsTable>

</div>

<q-dialog v-model="confirmDelete" persistent>
  <q-card>
    <q-card-section class="row warning-icon">
      <q-avatar icon="warning" color="primary" />
    </q-card-section>

      <q-card-section class="row items-center">
        <span class="q-ml-sm">{{ $t('msg_delete') }}</span>
      </q-card-section>

      <q-card-actions align="right">
        <q-btn flat :label="$t('cancel')" color="primary" v-close-popup />
        <q-btn
          flat
          :label="$t('delete')"
          color="primary"
          v-close-popup
          @click="deleteWorkflow()"
        />
      </q-card-actions>
    </q-card>
  </q-dialog>

  <q-dialog v-model="confirmBulkDelete" persistent>
    <q-card>
      <q-card-section class="row warning-icon">
        <q-avatar icon="warning" color="primary" />
      </q-card-section>
      <q-card-section class="row items-center">
        <span class="q-ml-sm">{{ $t('msg_delete') }} ({{ bulkDeleteIds.length }} Workflows)</span>
      </q-card-section>
      <q-card-actions align="right">
        <q-btn flat :label="$t('cancel')" color="primary" v-close-popup />
        <q-btn
          flat
          :label="$t('delete')"
          color="primary"
          v-close-popup
          @click="bulkDeleteWorkflows()"
        />
      </q-card-actions>
    </q-card>
  </q-dialog>

  <Loader />

<q-dialog v-model="executionOrderDialog">
  <q-card class="execution-order-dialog">
    <q-card-section>
      <div class="text-h6">{{ $t('edit_workflow_execution_order') }}</div>
      <div class="text-caption q-mt-xs">
        {{ $t('workflow_execution_order_desc') }}
      </div>
    </q-card-section>

    <q-card-section class="q-pt-none">
      <q-input
        v-model="executionOrderEditValue"
        type="number"
        outlined
        dense
        :min="EXECUTION_ORDER_MIN"
        :max="EXECUTION_ORDER_MAX"
        step="1"
        :label="$t('workflow_execution_order')"
        :rules="executionOrderRules"
        @keyup.enter="saveExecutionOrder()"
      />
    </q-card-section>

    <q-card-actions align="right">
      <q-btn flat :label="$t('cancel')" color="primary" v-close-popup />
      <q-btn
        flat
        :label="$t('save')"
        color="primary"
        :disable="!isExecutionOrderInputValid"
