<!-- Test Results Dialog -->
<WorkflowTestResultDialog
  v-model:visible="showTestResultsDialog"
  :test-results="testResults"
  :workflow-name="selectedTestWorkflow?.name || ''"
  :workflow-id="selectedTestWorkflow?.id || ''"
  @retest="testAdvancedWorkflow(selectedTestWorkflow)"
/>
</template>

<script lang="ts">
import { notify } from 'src/components/notifications/notify';
import { debounce } from 'quasar';
import { storeToRefs } from 'pinia';
import dateUtils from 'src/utils/date';
import { defineComponent, ref, computed } from 'vue';
import helperUtil from 'src/utils/helperUtil';
import Loader from 'src/components/Loader.vue';
import helperMixin from 'src/mixins/helperMixin';
import { workflowApiService } from 'src/services';
import { useSettingStore } from 'src/store/main';
import type { dynamicObj } from 'src/pages/assets';
import { ApiExceptions } from 'src/exceptions/index';
import { ADVANCED_WORKFLOW_SETTING_NAME } from 'src/pages/Settings/Components/Modules/workflowBuilderHelpers';
import { toBoolPreference } from 'src/utils/preferenceBool';
import {
  downloadWorkflowJson,
  hasAllowedFileType,
  importWorkflowJson,
} from 'src/pages/WorkflowBuilder/WorkflowComponnets/workflowImportExport';
import WorkflowTestResultDialog from 'src/pages/WorkflowBuilder/WorkflowComponnets/WorkflowTestResultDialog.vue';
import { prepareCard } from 'src/pages/WorkflowBuilder/generic_card_functions';
import { getWorkflowDetailRoute } from 'src/pages/WorkflowBuilder/workflowDashboardLogic';
import {
  buildWorkflowListQuery,
  forgetWorkflowListState,
  readSortFromControls,
  recallWorkflowListState,
  rememberWorkflowListState,
  resolveWorkflowListState,
  shouldFallBackToFirstPage,
  sortDirectionControlValue,
  DEFAULT_WORKFLOW_LIST_PAGE_SIZE,
  WORKFLOW_LIST_PAGE_SIZES,
  type WorkflowListViewState,
} from 'src/pages/WorkflowBuilder/workflowListUrlState';
import { i18n } from 'src/boot/i18n';
import { DocBitsTable } from 'src/components/Table';
import {
  applyColumnFilters,
  clearPersistedColumnFilters,
} from 'src/components/Table/composables/useColumnFilter';
import type {
  ColumnFilterValue,
  UnifiedTableColumn,
  TableFeatures,
  RowActionItem,
  RowActionPayload,
  RowClickPayload,
  TablePaginationState,
  PaginationChangePayload,
  SortEventPayload,
  BulkActionItem,
  BulkActionPayload,
} from 'src/components/Table';
import { BulkActionsMenu } from 'src/components/Table';

const WORKFLOW_LIST_TABLE_ID = 'workflow-list-table';

/**
 * Ceiling for the single request that backs a column filter. The list normally
 * pages server-side, but a column filter runs client-side, so while one is
 * active the whole matching set has to be in hand before a page is cut out of
 * it. The size actually asked for is the count the server last reported; this
 * only keeps a runaway count from turning into an unbounded request.
 */
const MAX_FILTERED_FETCH_LIMIT = 1000;

export default defineComponent({
  name: 'workFlow',
  mixins: [helperUtil, helperMixin, dateUtils],
  components: { Loader, DocBitsTable, BulkActionsMenu, WorkflowTestResultDialog },
  data() {
    return {
      workflowId: ref(''),
      searchBy: ref(''),
      tableData: [] as any[],
      confirmDelete: ref(false),
      selectedRecordIndex: ref(),
      version: ref(''),
      isLoading: false,
      showTestResultsDialog: ref(false),
      testResults: ref(null as any),
      testingWorkflow: ref(false),
      selectedTestWorkflow: ref(null as any),
      executionOrderDialog: false,
      executionOrderEditValue: '',
      executionOrderEditRow: null as any,
      openedOnPath: '',
      // The column filters the table currently has set. They are client-side, so
      // the list has to know about them to stop paging around them (BOL-498).
      columnFilters: [] as ColumnFilterValue[],
      // Last all_entries_count the server reported, i.e. the size of the set the
      // column filters run over. total_records follows the filter and cannot
      // serve as the fetch size once one is active.
      unfiltered_total_records: 0,
      // Guards the one retry a filtered load may make when the fetch size it
      // inherited turned out to be too small.
      refetchingForColumnFilters: false,
    };
  },

  // Before the first render, so the search box and pager never paint empty first.
  created() {
    this.openedOnPath = this.$route.path;

    // The table restores persisted filters in its own setup, without telling
    // anyone. Dropping them here - before that setup runs - keeps the filters no
    // wider than the view, so the list never pages against a filter it cannot
    // see. The matching clear on unmount covers a normal leave.
    clearPersistedColumnFilters(WORKFLOW_LIST_TABLE_ID);

    this.restoreListState();
  },

  async mounted() {
    this.debounceSearchInputFunc = debounce(() => {
      this.resetPagination();
      this.syncUrlWithListState();
      this.loadWorkFlow();
    }, 500);

    // Both before the first await: the list is what the user is waiting for, and
    // the autofocused search box needs its handler before it can be typed into.
    this.loadWorkFlow();

    document.removeEventListener('upload_files', this.uploadFilesEventHandler);
    document.addEventListener('upload_files', this.uploadFilesEventHandler);

    await this.getWorkflowVersion();
  },
  unmounted: function () {
    document.removeEventListener('upload_files', this.uploadFilesEventHandler);

    // A tab switch keeps the same path and is treated as leaving the list for
    // good, matching the column filters that get cleared just below. Only a real
    // navigation away is worth remembering, so a designer breadcrumb can return.
    // Must run before clearFilter(), which resets the sort order.
    if (this.$route.path === this.openedOnPath) {
      forgetWorkflowListState();
    } else {
      rememberWorkflowListState(this.currentListState());
    }

    // They are client-side, so a stale one hides rows the pager still counts.
    clearPersistedColumnFilters(WORKFLOW_LIST_TABLE_ID);

    this.clearFilter();
  },

  methods: {
    inputValueChanges() {
      this.debounceSearchInputFunc();
    },

    currentListState(): WorkflowListViewState {
      return {
        search: this.searchBy,
        page: this.current_page,
        pageSize: this.page_size,
        sort: readSortFromControls(
          this.sort_by.value,
          this.sort_direction.value,
        ),
      };
    },

    restoreListState() {
      const { state, restoredFromMemory } = resolveWorkflowListState({
        query: this.$route.query,
        previousPath: this.previousRoutePath(),
        remembered: recallWorkflowListState(),
      });

      this.searchBy = state.search;
      this.page_size = state.pageSize;
      this.current_page = state.page;
      this.sort_by = { value: state.sort.field, label: state.sort.field };
      this.sort_direction = {
        value: sortDirectionControlValue(state.sort),
        label: sortDirectionControlValue(state.sort),
      };
      this.calculateOffset();

      if (restoredFromMemory) {
        this.syncUrlWithListState();
      }
    },

    // Same source BreadCrumb.vue reads to decide which crumb chain applies.
    previousRoutePath(): string | null {
      const back = this.$router.options.history.state?.back;
      return typeof back === 'string' ? back : null;
    },

    syncUrlWithListState() {
      const query = buildWorkflowListQuery(
        this.currentListState(),
        this.$route.query,
      );
      // replace, so keystrokes do not pile up history entries.
      this.$router.replace({ query }).catch(() => {});
    },

    async getWorkflowVersion() {
      const res_version = await workflowApiService.getDocFlowVersion();
      this.version = res_version['docflow-version'];
    },

    // The when-condition cards this column renders carry no user, group or
    // sub-organisation variables, so there is no lookup data to supply.
    formatCard(card_item: dynamicObj): string {
      return prepareCard(card_item, {});
    },

    clearFilter() {
      this.sort_direction = { value: 'sort_desc', label: i18n.t('sort_desc') };
      this.sort_by = { value: 'created_on', label: i18n.t('log_created_on') };
    },

    async loadWorkFlow() {
      let response: any;

      try {
        this.isLoading = true;
        this.showLoading();
        this.request_params = {} as dynamicObj;
        // A column filter is applied after the response arrives, so the server
        // must not have cut a page out of the set first - the matches would be
        // left scattered over the pages they happened to land on (BOL-498).
        this.request_params['offset'] = this.hasColumnFilters ? 0 : this.offset;
        this.request_params['limit'] = this.hasColumnFilters
          ? this.filteredFetchLimit
          : this.page_size;
        if (this.sort_by.value && this.sort_direction.value) {
          this.request_params['order_by'] = this.sort_by.value;
          this.request_params['order_by_direction'] = this.sort_direction.value.replace('sort_', '');
        }
        if (this.searchBy !== '') {
          this.request_params['name'] = this.searchBy;
        }

        response = await workflowApiService.getWorkflowDashboard(
          this.request_params,
        );

        this.applyLoadedEntries(response.entries, response.all_entries_count);
      } catch (err) {
        const msg = ApiExceptions.getErrorMessage(err as dynamicObj);
        notify.error(msg);
        logError(err);
      } finally {
        this.isLoading = false;
        this.hideLoading();
      }

      // A filtered load asks for the count the previous one reported, so a set
      // that has grown - or a search that widened - can outrun it and leave the
      // filter looking at a truncated set. One retry with the fresh count closes
      // that gap; the count comes from the server, so it cannot ping-pong, and
      // the guard keeps a capped or short-answering server from looping.
      if (
        this.hasColumnFilters &&
        Array.isArray(response?.entries) &&
        !this.refetchingForColumnFilters &&
        response.entries.length <
          Math.min(this.unfiltered_total_records, MAX_FILTERED_FETCH_LIMIT)
      ) {
        this.refetchingForColumnFilters = true;
        try {
          await this.loadWorkFlow();
        } finally {
          this.refetchingForColumnFilters = false;
        }
        return;
      }

      // The rows on display, not the rows fetched: under a column filter the
      // response holds the whole set while the page cut from the matches can
      // still be empty.
      if (
        response?.entries &&
        shouldFallBackToFirstPage(this.tableData.length, this.current_page)
      ) {
        this.current_page = 1;
        this.calculateOffset();
        this.syncUrlWithListState();
        await this.loadWorkFlow();
      }
    },

    /**
     * Turns one response into what the table shows. Without a column filter the
     * server already cut the page, so the entries are the page. With one, the
     * entries are the whole set: the filter runs first and the page is cut from
     * the matches, so the matches stay together and the pager counts them
     * instead of the rows the filter hides (BOL-498).
     */
    applyLoadedEntries(entries: any[] | undefined, allEntriesCount: number) {
      this.unfiltered_total_records = allEntriesCount || 0;

      if (!this.hasColumnFilters) {
        if (Array.isArray(entries)) {
          this.tableData = entries;
        }
        this.total_records = allEntriesCount;
        this.setTotalPages();
        return;
      }

      const matches = applyColumnFilters(
        Array.isArray(entries) ? entries : [],
        this.columnFilters,
        this.tableColumns,
      );

      this.total_records = matches.length;
      this.setTotalPages();

      const start = this.page_size * (this.current_page - 1);
      this.tableData = matches.slice(start, start + this.page_size);
    },

    /**
     * A narrowed set has fewer pages than the one the user is looking at, so the
     * page they sit on may not exist any more - and a filter meant for the whole
     * list must not be answered out of the single page in hand.
     */
    handleColumnFiltersChange(payload: { filters?: ColumnFilterValue[] }) {
      this.columnFilters = Array.isArray(payload?.filters)
        ? [...payload.filters]
        : [];
      this.current_page = 1;
      this.calculateOffset();
      this.syncUrlWithListState();
      this.loadWorkFlow();
    },

    async handleActive(row: any, isActive: boolean) {
      let response: any;
      let isNewCase = null;
      try {
        let workflowData = {} as any;
        workflowData.id = row.id;
        // workflowData.name = row.name;
        workflowData.enabled = isActive;

        response = await workflowApiService.updateWorkflow(workflowData);
        if (response) {
          notify.success(this.$t('MSG_SAVE'));
          row.enabled = isActive;
          // Dispatch event to notify dashboard of status change
          const event = new CustomEvent('workflow_status_changed', {
            detail: { workflowId: row.id, enabled: isActive }
          });
          document.dispatchEvent(event);
        }
        isNewCase = false;
      } catch (err) {
        const msg = ApiExceptions.getErrorMessage(err as dynamicObj);
        notify.error(msg);
        logError(err);
        isNewCase = null;
      }
    },

    openExecutionOrderDialog(row: any) {
      this.executionOrderEditRow = row;
      this.executionOrderEditValue = String(row.sort_order);
      this.executionOrderDialog = true;
    },

    async saveExecutionOrder() {
      if (!this.isExecutionOrderInputValid || !this.executionOrderEditRow) return;

      const row = this.executionOrderEditRow;
      const nextValue = Number(this.executionOrderEditValue);
      if (row.sort_order === nextValue) {
        this.executionOrderDialog = false;
        return;
      }

      try {
        this.showLoading();
        await workflowApiService.updateWorkflow({ id: row.id, sort_order: nextValue });
        row.sort_order = nextValue;
        notify.success(this.$t('MSG_SAVE'));
        this.executionOrderDialog = false;
      } catch (err) {
        const msg = ApiExceptions.getErrorMessage(err as dynamicObj);
        notify.error(msg);
        logError(err);
      } finally {
        this.hideLoading();
      }
    },

    async deleteWorkflow() {
      let response: any;

      try {
        this.showLoading();
        response = await workflowApiService.deleteWorkflow(this.workflowId);
        notify.success(this.$t('DELETED_SUCCESSFULLY'));
        this.tableData.splice(this.selectedRecordIndex, 1);
      } catch (err) {
        const msg = ApiExceptions.getErrorMessage(err as dynamicObj);
        notify.error(msg);
        logError(err);
      } finally {
        this.hideLoading();
      }
    },

    handleBulkAction(actionKey: string, selectedIds: string[]) {
      switch (actionKey) {
        case 'activate':
          this.bulkToggleWorkflows(selectedIds, true);
          break;
        case 'deactivate':
          this.bulkToggleWorkflows(selectedIds, false);
          break;
        case 'delete':
          this.bulkDeleteIds = selectedIds;
          this.confirmBulkDelete = true;
          break;
      }
    },

    async bulkToggleWorkflows(ids: string[], enabled: boolean) {
      try {
        this.showLoading();
        const result = (await workflowApiService.bulkToggleWorkflows(ids, enabled)) as {
          success?: string[];
          failed?: string[];
        };
        if (result.success?.length) {
          for (const id of result.success) {
            const row = this.tableData.find((r: any) => r.id === id);
            if (row) row.enabled = enabled;
          }
          notify.success(
            `${result.success.length} ${enabled ? this.$t('activate') : this.$t('deactivate')}`,
          );
        }
        if (result.failed?.length) {
          notify.error(`${result.failed.length} workflows failed`);
        }
      } catch (err) {
        const msg = ApiExceptions.getErrorMessage(err as dynamicObj);
        notify.error(msg);
        logError(err);
      } finally {
        this.hideLoading();
      }
    },

    async bulkDeleteWorkflows() {
      try {
        this.showLoading();
        const result = (await workflowApiService.bulkDeleteWorkflows(this.bulkDeleteIds)) as {
          success?: string[];
          failed?: string[];
        };
        if (result.success?.length) {
          const successIds = result.success;
          this.tableData = this.tableData.filter(
            (r: any) => !successIds.includes(r.id),
          );
          notify.success(this.$t('DELETED_SUCCESSFULLY'));
        }
        if (result.failed?.length) {
          notify.error(`${result.failed.length} workflows failed to delete`);
        }
        this.bulkDeleteIds = [];
      } catch (err) {
        const msg = ApiExceptions.getErrorMessage(err as dynamicObj);
        notify.error(msg);
        logError(err);
      } finally {
        this.hideLoading();
      }
    },

    async convertToAdvanced(row: any) {
      try {
        this.showLoading();
        const response = await workflowApiService.convertToAdvanced(row.id);
        notify.success(this.$t('convert_to_advanced_success'));
        // Navigate to the new advanced workflow
        if (response?.workflow_id || response?.id) {
          this.$router.push(getWorkflowDetailRoute(response.workflow_id || response.id, 'advanced'));
        } else {
          await this.loadWorkFlow();
        }
      } catch (err) {
        const msg = ApiExceptions.getErrorMessage(err as dynamicObj);
        notify.error(msg);
        logError(err);
      } finally {
        this.hideLoading();
      }
    },

    async copyWorkflow(wprkflowId: any) {
      let response: any;

      try {
        this.showLoading();
        response = await workflowApiService.copyWorkflow(wprkflowId);
        notify.success(this.$t('MSG_SAVE'));

        this.tableData.splice(0, 0, JSON.parse(JSON.stringify(response)));
        await this.loadWorkFlow();
      } catch (err) {
        const msg = ApiExceptions.getErrorMessage(err as dynamicObj);
        notify.error(msg);
        logError(err);
      } finally {
        this.hideLoading();
      }
    },

    openWorkflowDesigner(workFlowId: string, workflowType?: string) {
      // Leaving is not debounced, so the URL can still be a keystroke behind.
      this.syncUrlWithListState();
      this.$router.push(getWorkflowDetailRoute(workFlowId, workflowType));
    },

    async downloadWorkflow(row: any) {
      try {
        this.showLoading();
        await downloadWorkflowJson(row.id, row.name);
      } catch (err) {
        const msg = ApiExceptions.getErrorMessage(err as dynamicObj);
        notify.error(msg);
        logError(err);
      } finally {
        this.hideLoading();
      }
    },

    async testAdvancedWorkflow(row: any) {
      try {
        this.testingWorkflow = true;
        this.selectedTestWorkflow = row;
        this.showLoading();

        const response = (await workflowApiService.testAdvancedWorkflow({
          workflow_id: row.id,
        })) as { data?: { success?: boolean; message?: string } };

        if (response?.data?.success) {
          this.testResults = response.data;
          this.showTestResultsDialog = true;
          notify.success(
            this.$t('workflow_test_completed')
          );
        } else {
          notify.error(
            response?.data?.message || this.$t('workflow_test_failed')
          );
        }
      } catch (err) {
        const msg = ApiExceptions.getErrorMessage(err as dynamicObj);
        notify.error(msg);
        logError(err);
      } finally {
        this.testingWorkflow = false;
        this.hideLoading();
      }
    },

    resetPagination() {
      this.offset = 0;
      this.total_pages = 0;
      this.current_page = 1;
      this.total_records = 0;
    },

    setTotalPages() {
      this.total_pages = Math.ceil(this.total_records / this.page_size);
    },

    async nexPageClicked() {
      try {
        this.calculateOffset();
        await this.loadWorkFlow();
      } catch (err: any) {
        const msg = ApiExceptions.getErrorMessage(err as dynamicObj);
        notify.error(msg);
        logError(err);
      }
    },

    calculateOffset() {
      this.offset = this.page_size * (this.current_page - 1);
    },

    uploadFile(value: any) {
      this.uploadedFiles = value;
      let file = this.uploadedFiles;
      if (!file) {
        notify.error(this.$t('NO_FILE_SELECTED'));
      }
      this.uploadFiles(file);
    },

    uploadFilesEventHandler(e: any) {
      if (!e || !e.detail.files) {
        return;
      }
      this.uploadFiles(e.detail.files);
    },

    async uploadFiles(files: any) {
      try {
        this.multiUploaderDialog = false;
        this.uploadedFiles = null;

        if (files && files.length > 10) {
          notify.error(this.$t('max_workflow_upload_limit'));
          return;
        }

        this.formData = new FormData();
        let invalidFileCounter = 0;

        for (let file of files) {
          if (hasAllowedFileType(file)) {
            this.formData.append('workflow_json', file);
          } else {
            invalidFileCounter++;
          }
        }

        if (invalidFileCounter > 0) {
          notify.error(this.$t('INVALID_FILES'));
          return;
        }
        await this.uploadWorkflowJson(this.formData);
      } catch (err: any) {
        const msg = ApiExceptions.getErrorMessage(err as dynamicObj);
        notify.error(msg);
        logError(err);
      } finally {
        const event = new CustomEvent('table_data_updated', {});
        document.dispatchEvent(event);
      }
    },

    async uploadWorkflowJson(formData: FormData) {
      try {
        const response = await importWorkflowJson(formData);
        if (response.success === false) {
          logError(response);
          notify.error(this.$t('DOC_UPLOAD_ERROR'));
          notify.error(response.message);
          return;
        }
      } catch (err: any) {
        const msg = ApiExceptions.getErrorMessage(err as dynamicObj);
        notify.error(msg);
        logError(err);
      } finally {
        await this.loadWorkFlow();
      }
    },

    workflowTestRoute() {
      this.$router.push('/workflows_task_manager');
    },

    // DocBitsTable event handlers
    handleRowClick(payload: RowClickPayload) {
      this.openWorkflowDesigner(payload.row.id, payload.row.workflow_type);
    },

    handleRowAction(payload: RowActionPayload) {
      const { action, row } = payload;
      switch (action) {
        case 'activate':
          this.handleActive(row, true);
          break;
        case 'deactivate':
          this.handleActive(row, false);
          break;
        case 'test':
          this.testAdvancedWorkflow(row);
          break;
        case 'convert_to_advanced':
          this.convertToAdvanced(row);
          break;
        case 'duplicate':
          this.copyWorkflow(row.id);
          break;
        case 'edit':
          this.openWorkflowDesigner(row.id, row.workflow_type);
          break;
        case 'download':
          this.downloadWorkflow(row);
          break;
        case 'edit_sort_order':
          this.openExecutionOrderDialog(row);
          break;
        case 'delete':
          this.workflowId = row.id;
          this.confirmDelete = true;
          this.selectedRecordIndex = this.tableData.findIndex((item: any) => item.id === row.id);
          break;
      }
    },

    handlePaginationChange(payload: PaginationChangePayload) {
      this.page_size = payload.rowsPerPage;
      this.current_page = payload.page;
      this.calculateOffset();
      this.syncUrlWithListState();
      this.loadWorkFlow();
    },

    handleSortChange(payload: SortEventPayload) {
      if (payload.direction === null) {
        this.sort_by = { value: '', label: '' };
        this.sort_direction = { value: '', label: '' };
      } else {
        const columnToField: Record<string, string> = {
          'name': 'name',
          'created_on': 'created_on',
          'last_modified_on': 'last_modified_on',
        };
        const fieldName = columnToField[payload.column] || payload.column;
        this.sort_by = { value: fieldName, label: fieldName };
        this.sort_direction = {
          value: payload.direction === 'desc' ? 'sort_desc' : 'sort_asc',
          label: payload.direction === 'desc' ? 'sort_desc' : 'sort_asc',
        };
      }

      // Reset to first page when sorting changes
      this.current_page = 1;
      this.offset = 0;
      this.syncUrlWithListState();
      this.loadWorkFlow();
    },
  },
  computed: {
    hasColumnFilters(): boolean {
      return this.columnFilters.length > 0;
    },

    /**
     * How many rows one filtered load asks for: the count the server last
     * reported, never fewer than a page, and capped so a runaway count cannot
     * turn into an unbounded request.
     */
    filteredFetchLimit(): number {
      return Math.min(
        Math.max(this.unfiltered_total_records, this.page_size),
        MAX_FILTERED_FETCH_LIMIT,
      );
    },

    tablePagination(): TablePaginationState {
      return {
        sortBy: this.sort_by.value,
        descending: this.sort_direction.value === 'sort_desc',
        page: this.current_page,
        rowsPerPage: this.page_size,
        rowsNumber: this.total_records,
      };
    },
    executionOrderRules(): Array<(v: unknown) => true | string> {
      const msg = this.$t('workflow_execution_order_invalid', {
        min: this.EXECUTION_ORDER_MIN,
        max: this.EXECUTION_ORDER_MAX,
      });
      return [
        (v: unknown) => {
          const trimmed = typeof v === 'string' ? v.trim() : v;
          if (trimmed === '' || trimmed == null) return msg;
          const n = Number(trimmed);
          return (
            (Number.isInteger(n) &&
              n >= this.EXECUTION_ORDER_MIN &&
              n <= this.EXECUTION_ORDER_MAX) ||
            msg
          );
        },
      ];
    },
    isExecutionOrderInputValid(): boolean {
      return this.executionOrderRules.every(
        (rule) => rule(this.executionOrderEditValue) === true,
      );
    },
  },
  setup() {
    const settings_store = useSettingStore();
    const { user_settings } = storeToRefs(settings_store);

    const formatTs = (value: string): string => {
      return dateUtils.methods.formatDateAccordingToPreference.call(dateUtils.methods, value);
    };

    // Table columns definition - fixed widths prevent column shifting on sort
    const tableColumns = computed<UnifiedTableColumn[]>(() => [
      {
        name: 'name',
        label: i18n.t('name'),
        field: 'name',
        align: 'left',
        sortable: true,
        style: 'width: 300px; min-width: 300px;',
        headerStyle: 'width: 300px; min-width: 300px;',
      },
      {
        name: 'workflow_type',
        label: i18n.t('type'),
        field: 'workflow_type',
        align: 'center',
        sortable: false,
        style: 'width: 100px; min-width: 100px;',
        headerStyle: 'width: 100px; min-width: 100px;',
      },
      {
        name: 'sort_order',
        label: i18n.t('workflow_execution_order'),
        field: 'sort_order',
        align: 'center',
        sortable: false,
        filter: false,
        style: 'width: 130px; min-width: 130px;',
        headerStyle: 'width: 130px; min-width: 130px;',
      },
      {
        name: 'when_condition',
        label: i18n.t('wf_when'),
        field: 'when_condition',
        align: 'left',
        sortable: false,
        filter: false,
        style: 'width: 250px; min-width: 250px;',
        headerStyle: 'width: 250px; min-width: 250px;',
      },
      {
        name: 'last_modified_by_name',
        label: i18n.t('last_saved_by'),
        field: 'last_modified_by_name',
        align: 'left',
        sortable: false,
        style: 'width: 140px; min-width: 140px;',
        headerStyle: 'width: 140px; min-width: 140px;',
      },
      {
        name: 'created_on',
        label: i18n.t('log_created_on'),
        field: 'created_on',
        align: 'left',
        sortable: true,
        style: 'width: 170px; min-width: 170px;',
        headerStyle: 'width: 170px; min-width: 170px;',
        filterValue: (v: string) => formatTs(v),
      },
      {
        name: 'last_modified_on',
        label: i18n.t('last_modified_on'),
        field: 'last_modified_on',
        align: 'left',
        sortable: true,
        style: 'width: 170px; min-width: 170px;',
        headerStyle: 'width: 170px; min-width: 170px;',
        filterValue: (v: string) => formatTs(v),
      },
    ]);

    // Table features configuration
    const tableFeatures = computed<Partial<TableFeatures>>(() => ({
      sorting: true,
      selection: true,
      bulkActions: true,
      rowActions: true,
      pagination: true,
      resizable: false,
      columnReorder: false,
    }));

    const bulkActions = computed<BulkActionItem[]>(() => [
      {
        key: 'activate',
        label: 'activate',
        icon: 'toggle_on',
        color: 'positive',
        minSelected: 1,
      },
      {
        key: 'deactivate',
        label: 'deactivate',
        icon: 'toggle_off',
        minSelected: 1,
      },
      {
        key: 'delete',
        label: 'delete_action',
        icon: 'delete',
        color: 'negative',
        separator: true,
        minSelected: 1,
      },
    ]);

    // Row actions configuration
    // SVG icon classes: black_to_white for dark icons, invert for white icons
    const rowActions = computed<RowActionItem[]>(() => [
      {
        key: 'activate',
        label: 'activate',
        icon: 'toggle_on',
        color: 'positive',
        show: (row) => !row.enabled,
      },
      {
        key: 'deactivate',
        label: 'deactivate',
        icon: 'toggle_off',
        show: (row) => row.enabled,
      },
      {
        key: 'test',
        label: 'test_workflow',
        icon: 'play_circle',
        color: 'primary',
        show: (row) => row.workflow_type === 'advanced',
      },
      {
        key: 'convert_to_advanced',
        label: 'convert_to_advanced',
        icon: 'upgrade',
        color: 'deep-purple',
        show: (row) => row.workflow_type !== 'advanced' && toBoolPreference(user_settings.value[ADVANCED_WORKFLOW_SETTING_NAME]),
      },
      {
        key: 'duplicate',
        label: 'duplicate',
        icon: 'content_copy',
      },
      {
        key: 'edit',
        label: 'edit',
        icon: 'edit',
      },
      {
        key: 'download',
        label: 'download',
        icon: 'download',
      },
      {
        key: 'edit_sort_order',
        label: 'edit_workflow_execution_order',
        icon: 'swap_vert',
      },
      {
        key: 'delete',
        label: 'delete_action',
        icon: 'delete',
        color: 'negative',
        separator: true,
      },
    ]);

    return {
      debounceSearchInputFunc: {} as any,
      request_params: ref({} as dynamicObj),
      current_page: ref(1),
      total_pages: ref(1),
      offset: ref(0),
      page_size: ref(DEFAULT_WORKFLOW_LIST_PAGE_SIZE),
      total_records: ref(0),
      multiUploaderDialog: ref(false),
      uploadedFiles: ref(null),
      formData: {} as FormData,
      sort_direction: ref({ value: 'sort_desc', label: 'sort_desc' }),
      sort_by: ref({ value: 'created_on', label: 'log_created_on' }),
      pageSizeOptions: [...WORKFLOW_LIST_PAGE_SIZES],
      tableId: WORKFLOW_LIST_TABLE_ID,
      tableColumns,
      tableFeatures,
      rowActions,
      bulkActions,
      confirmBulkDelete: ref(false),
      bulkDeleteIds: ref<string[]>([]),
      EXECUTION_ORDER_MIN: 0,
      EXECUTION_ORDER_MAX: 1000,
    };
  },
});
</script>

