<template>
  <div class="q-pa-md">
    <div class="text-h6 q-mb-md">{{ $t('license_management') }}</div>

    <q-banner v-if="error" class="bg-negative text-white q-mb-md" rounded>
      {{ error }}
    </q-banner>

    <div class="row q-col-gutter-md">
      <!-- Workflow License Card -->
      <div class="col-12 col-md-6">
        <q-card bordered>
          <q-card-section>
            <div class="row items-center justify-between">
              <div>
                <div class="text-subtitle1 text-weight-bold">
                  {{ $t('workflow') }}
                </div>
                <div class="text-caption text-grey">
                  {{ $t('license_workflow_description') }}
                </div>
              </div>
              <f-toggle
                v-model="user_settings[setting_name]"
                color="primary"
                @update:model-value="(val: boolean) => setWorkflowBuilder(val)"
              />
            </div>
          </q-card-section>
          <q-separator />
          <q-card-section>
            <q-badge
              :color="user_settings[setting_name] ? 'positive' : 'grey'"
              :label="user_settings[setting_name] ? $t('active') : $t('inactive')"
            />
          </q-card-section>
        </q-card>
      </div>

      <!-- Advanced Workflow License Card -->
      <div class="col-12 col-md-6">
        <q-card bordered>
          <q-card-section>
            <div class="row items-center justify-between">
              <div>
                <div class="text-subtitle1 text-weight-bold">
                  {{ $t('advanced_workflow') }}
                </div>
                <div class="text-caption text-grey">
                  {{ $t('license_advanced_workflow_description') }}
                </div>
              </div>
              <f-toggle
                v-model="user_settings[advanced_setting_name]"
                color="primary"
                @update:model-value="(val: boolean) => setAdvancedWorkflow(val)"
              />
            </div>
          </q-card-section>
          <q-separator />
          <q-card-section>
            <q-badge
              :color="user_settings[advanced_setting_name] ? 'positive' : 'grey'"
              :label="user_settings[advanced_setting_name] ? $t('active') : $t('inactive')"
            />
          </q-card-section>
        </q-card>
      </div>
    </div>

    <subscription-dialog
      v-model="show_popup"
      :settings="settings"
      :settingType="activeDialog.setting"
      :appKey="activeDialog.appKey"
      :preferredAppKey="activeDialog.preferredAppKey"
      :manageCreate="activeDialog.manageCreate"
      :onConfirm="activeDialog.confirmHandler"
    />

    <q-inner-loading :showing="loading" />
  </div>
</template>

<script lang="ts">
import { defineComponent, ref } from 'vue';
import { storeToRefs } from 'pinia';
import { useSettingStore } from 'src/store/main';
import { preferencesService } from 'src/services/preferences/preferencesService';
import { toBoolPreference } from 'src/utils/preferenceBool';
import helperMixin from 'src/mixins/helperMixin.js';
import subscriptionDialog from 'src/pages/Settings/Components/Subscription/SubscriptionDialog.vue';
import {
  WORKFLOW_SETTING_NAME,
  WORKFLOW_DOC_FLOW_KEY,
  ADVANCED_WORKFLOW_SETTING_NAME,
  ADVANCED_WORKFLOW_APP_KEY,
  saveSettingsImpl,
  setWorkflowBuilderImpl,
  deactivateWorkflowSubscription,
  handleSubscriptionConfirmImpl,
  onLoadingSettingsChange,
  configureCombinedWorkflowDialog,
  configureAdvancedWorkflowDialog,
} from 'src/pages/Settings/Components/Modules/workflowBuilderHelpers';
import type { ActiveDialogState } from 'src/pages/Settings/Components/Modules/workflowBuilderHelpers';

export default defineComponent({
  name: 'WorkflowLicense',
  mixins: [helperMixin],
  components: {
    subscriptionDialog,
  },

  setup() {
    const settings_store = useSettingStore();
    const { updateSetting, setSetting } = settings_store;
    const { user_settings, loading_settings } = storeToRefs(settings_store);

    return {
      updateSetting,
      setSetting,
      user_settings,
      loading_settings,
      loading: ref(false),
      error: ref(''),
      show_popup: ref(false),
      setting_name: WORKFLOW_SETTING_NAME,
      advanced_setting_name: ADVANCED_WORKFLOW_SETTING_NAME,
      settings: {} as Record<string, any>,
      activeDialog: {
        setting: WORKFLOW_SETTING_NAME,
        appKey: WORKFLOW_DOC_FLOW_KEY as string | string[],
        preferredAppKey: '',
        manageCreate: true,
        confirmHandler: null,
      } as ActiveDialogState,
    };
  },

  watch: {
    loading_settings: {
      handler(newVal: boolean, oldVal: boolean) {
        onLoadingSettingsChange(this, newVal, oldVal);
      },
    },
  },

  async mounted() {
    await this.refreshLicenseSettings();
  },

  methods: {
    // The settings store only fetches once at app startup, so the cached
    // user_settings can be stale by the time the license tab opens. Pull all
    // org preferences fresh in a single bulk call and update the two module
    // settings so the toggles reflect current server state.
    async refreshLicenseSettings() {
      this.loading = true;
      try {
        const prefs = await preferencesService.getAllOrgPreferences();
        // toBoolPreference: prefs come back as raw preference strings from
        // the bulk untyped endpoint. The store's own getSettingValue() only
        // recognizes clean "true"/"false", so legacy encodings ("0"/"1"/
        // "yes"/"no") would pass through as truthy JS strings and the
        // template's `user_settings[setting_name] ? ... : ...` bindings
        // would render the wrong state (DRFS-626 class bug).
        this.setSetting(
          this.setting_name,
          toBoolPreference(prefs[this.setting_name]),
        );
        this.setSetting(
          this.advanced_setting_name,
          toBoolPreference(prefs[this.advanced_setting_name]),
        );
      } finally {
        this.loading = false;
      }
    },
    async saveSettings(key: string, value: any) {
      await saveSettingsImpl(this, key, value);
    },
    async setWorkflowBuilder(val: boolean) {
      if (val) {
        configureCombinedWorkflowDialog(this);
        await setWorkflowBuilderImpl(this, val);
      } else {
        await this.deactivateAndCatch(
          WORKFLOW_DOC_FLOW_KEY,
          WORKFLOW_SETTING_NAME,
          'Failed to deactivate workflow',
        );
      }
    },
    async setAdvancedWorkflow(val: boolean) {
      if (val) {
        configureAdvancedWorkflowDialog(this);
        this.show_popup = true;
      } else {
        await this.deactivateAndCatch(
          ADVANCED_WORKFLOW_APP_KEY,
          ADVANCED_WORKFLOW_SETTING_NAME,
          'Failed to deactivate advanced workflow',
        );
      }
    },
    handleSubscriptionConfirm(value: any) {
      handleSubscriptionConfirmImpl(this, value);
    },
    async deactivateAndCatch(
      appKey: string,
      settingName: string,
      errorFallback: string,
    ) {
      // Wraps `deactivateWorkflowSubscription` with this view's banner-error
      // surface (the q-banner above) so failures don't disappear into the void.
      try {
        await deactivateWorkflowSubscription(this, appKey, settingName);
      } catch (err: any) {
        this.error = err?.message || errorFallback;
        throw err;
      }
    },
  },
});
</script>
