<template>
  <q-card class="main-container">
    <div class="workflow-kpi-card">
      <!-- Loading State -->
      <div v-if="loading" class="skeleton-loader">
        <div class="skeleton-text skeleton-text-1"></div>
        <div class="skeleton-text skeleton-text-2"></div>
        <div class="skeleton-text skeleton-text-3"></div>
      </div>

      <div v-else class="kpi-content">
        <div class="kpi-main-content">
          <div class="kpi-value">{{ formatValue(value) }}</div>
          <div v-if="badge && showBadge" class="mb-4">
            <span :class="['kpi-badge', `badge-${statusColor}`]">
              {{ badge }}
            </span>
          </div>
          <div class="kpi-title">{{ title }}</div>
          <div v-if="subtitle" class="kpi-subtitle">{{ subtitle }}</div>
        </div>

        <div v-if="showComparison" class="comparison-section">
          <div class="comparison-divider"></div>
          <div class="comparison-content">
            <div class="comparison-value">{{ formatValue(compareValue) }}</div>

            <div
              v-if="delta !== undefined && delta !== null"
              :class="['delta-badge', getDeltaClass()]"
            >
              <span class="delta-icon">{{ delta >= 0 ? '↑' : '↓' }}</span>
              <span class="delta-value">{{ getFormattedDelta() }}</span>
            </div>
          </div>
        </div>
      </div>
    </div>
  </q-card>
</template>

<script lang="ts">
import { defineComponent } from 'vue';

export default defineComponent({
  name: 'WorkflowKpiCard',
  props: {
    title: String,
    subtitle: String,
    value: [Number, String],
    loading: Boolean,
    badge: String,
    statusColor: String,
    showComparison: Boolean,
    compareValue: [Number, String],
    delta: Number,
    showBadge: {
      type: Boolean,
      default: true,
    },
  },
  methods: {
    formatValue(val: number | string | undefined): string {
      if (val === null || val === undefined) return '—';
      if (typeof val === 'number') return val.toLocaleString('en-US');
      return String(val);
    },
    getDeltaClass(): string {
      if (this.delta === undefined || this.delta === null) return '';
      return this.delta >= 0 ? 'delta-positive' : 'delta-negative';
    },
    getFormattedDelta(): string {
      if (this.delta === undefined || this.delta === null) return '';
      const abs = Math.abs(this.delta);
      const sign = this.delta >= 0 ? '+' : '-';
      return `${sign}${abs.toLocaleString('en-US')}`;
    },
  },
});
</script>

