<template>
  <q-card class="main-card">
    <q-toolbar class="text-white secondary-toolbar">
      <q-toolbar-title>
        <span class="text-weight-bold">{{
          $t('workflow_test_scenario_logs')
        }}</span>
      </q-toolbar-title>
      <q-btn flat round dense icon="close" v-close-popup />
    </q-toolbar>
    <q-card-section class="q-pa-none">
      <div v-for="row in rows" :key="row.workflow_id">
        <div class="row horizontal-divider">
          <div class="col-4 q-pa-sm text-center vertical-divider">
            {{ $t('last_run_time') }}
          </div>
          <div class="col-8 q-pa-sm text-center">{{ $t('result') }}</div>
        </div>

        <div class="row horizontal-divider">
          <div class="col-4 q-pa-sm text-center vertical-divider">
            {{ formatDateAccordingToPreference(row.created_on) }}
          </div>
          <div class="col-8 q-pa-sm text-center">
            <q-icon
              v-if="row.status === 'Pass'"
              name="check_circle"
              color="green"
              size="sm"
            />
            <q-icon
              v-else-if="
                row.status === null || row.status === 'failed_condition'
              "
              name="do_not_disturb_on"
              color="orange"
              size="sm"
            />
            <q-icon v-else name="cancel" color="red" size="sm" />
          </div>
        </div>

        <div class="row">
          <div class="col-4 q-pa-md vertical-divider">
            <div
              v-if="
                row.workflow_data &&
                row.workflow_data.data?.when_condition?.card_logs != undefined
              "
            >
              <div class="card-category-text">{{ $t('wf_when') }}</div>
              <GenericCard
                :card_result="checkCardSuccess(row.workflow_id, 0, 'when')"
                :item="row.workflow_data.data.when_condition"
                :version="row.workflow_data.data.when_condition.version"
                @click="
                  getCardLogs(
                    row.workflow_data.data.when_condition.id,
                    row.workflow_id,
                    0,
                    'when',
                  )
                "
              />

              <div class="card-category-text">{{ $t('wf_and') }}</div>
              <div
                v-for="(item, index) in row.workflow_data.data.and_conditions"
                :key="item.id + '_' + item.card_version + '_' + index"
              >
                <GenericCard
                  :card_result="checkCardSuccess(row.workflow_id, index, 'and')"
                  :item="item"
                  :version="item.version"
                  @click="getCardLogs(item.id, row.workflow_id, index, 'and')"
                />
              </div>

              <div class="card-category-text">{{ $t('wf_then') }}</div>
              <div
                v-for="(item, index) in row.workflow_data.data.then_conditions"
                :key="item.id + '_' + item.card_version + '_' + index"
              >
                <GenericCard
                  :card_result="
                    checkCardSuccess(row.workflow_id, index, 'then')
                  "
                  :item="item"
                  :version="item.version"
                  @click="getCardLogs(item.id, row.workflow_id, index, 'then')"
                />
              </div>
            </div>
          </div>

          <div class="col-8 q-pa-md">
            <div class="small-heading">
              <div
                v-if="
                  row.workflow_data &&
                  row.workflow_data.data?.when_condition?.card_logs
                "
              >
                {{ $t('wf_card_logs') }}
              </div>
              <div v-else>
                {{ $t('wf_workflow_logs') }}
              </div>
            </div>
            <div v-if="displayed_messages[row.workflow_id]">
              <div
                v-for="(message, index) in displayed_messages[row.workflow_id]"
                :key="index"
              >
                <span
                  v-if="message.translation_key"
                  class="card-message q-my-sm"
                >
                  {{
                    $t(
                      'wf_log.' + message.translation_key,
                      translateDataLocal(message.data),
                    )
                  }}
                </span>
                <span v-else class="card-message q-my-sm">{{
                  message.message
                }}</span>
              </div>
            </div>
            <div v-else>
              {{ $t('wf_card_logs_message') }}
            </div>
          </div>
        </div>
      </div>
    </q-card-section>
  </q-card>
</template>

<script lang="ts">
import { defineComponent, ref } from 'vue';
import dateUtils from 'src/utils/date';
import GenericCard from '../workflowLogs/generic_card_logs.vue';
import { dynamicObj } from '../../assets';
import { storeToRefs } from 'pinia';
import { useWorkflowLogsVariablesStore } from 'src/store/WorkflowBuilder/workflow_logs_variables.store';

export default defineComponent({
  name: 'workflowTestLogs',
  props: {
    workflowLog: {
      type: [Array, Object] as any,
      required: false,
    },
  },
  components: {
    GenericCard,
  },
  mixins: [dateUtils],
  watch: {
    workflowLog: {
      handler(newVal) {
        this.prepareRows();
      },
      deep: true,
      immediate: true,
    },
  },
  methods: {
    prepareRows() {
      if (typeof this.workflowLog === 'object' && this.workflowLog !== null) {
        this.rows = [
          {
            test_scenario_name: this.workflowLog.test_scenario_name,
            created_on: this.workflowLog.created_on,
            run_time_seconds: (
              this.workflowLog.run_time_mili_seconds / 1000
            ).toFixed(2),
            status: this.workflowLog.status,
            workflow_data: this.workflowLog.logs.workflow_data,
            workflow_id: this.workflowLog.workflow_id,
          },
        ];
        this.logs = this.workflowLog.logs;
      } else {
        this.rows = [];
      }
    },

    getCardLogs(
      card_id: string,
      workflow_run_id: string,
      index: any,
      run_category: string,
    ) {
      if (
        !Object.keys(this.card_messages).includes(
          card_id.toString() +
            workflow_run_id.toString() +
            index +
            '_' +
            run_category,
        )
      ) {
        this.prepareCardLogs(card_id, workflow_run_id, index, run_category);
      }

      this.displayed_messages[workflow_run_id.toString()] =
        this.card_messages[
          card_id.toString() +
            workflow_run_id.toString() +
            index +
            '_' +
            run_category
        ];
    },

    prepareCardLogs(
      card_id: string,
      workflow_run_id: string,
      index: any,
      run_category: string,
    ) {
      const workflow_log = this.logs;
      const full_workflow_log = this.logs;
      return this.workflowprepareCardLogs(
        full_workflow_log,
        workflow_log,
        card_id,
        workflow_run_id,
        index,
        run_category,
      );
    },

    checkCardSuccess(
      workflow_run_id: string,
      index: any,
      run_category: string,
    ) {
      try {
        const workflow_log = this.logs;
        const full_workflow_log = this.logs;
        return this.checkLogSuccessCards(
          full_workflow_log,
          workflow_log,
          run_category,
          index,
        );
      } catch (err) {
        logError(err);
      }
    },

    translateDataLocal(data: dynamicObj) {
      return this.translateData(data);
    },
  },
  setup() {
    const workflowVariableStore = useWorkflowLogsVariablesStore();
    const { checkLogSuccessCards, workflowprepareCardLogs, translateData } =
      workflowVariableStore;
    const { logs, wf_logs, card_messages } = storeToRefs(workflowVariableStore);
    const columns = [
      {
        name: 'created_on',
        required: false,
        label: 'Created On',
        align: 'left',
        field: 'created_on',
        headerClasses: 'table-header-wf-logs',
      },
      {
        name: 'status',
        required: false,
        label: 'Results',
        align: 'center',
        field: 'status',
        style: ' align-items: center; justify-content: center;',
        headerClasses: 'table-header-wf-logs',
      },
    ];

    return {
      translateData,
      checkLogSuccessCards,
      workflowprepareCardLogs,
      displayed_messages: ref({} as dynamicObj),
      columns,
      rows: ref([] as any),
      wf_logs,
      logs,
      card_messages,
      workflows: ref({} as any),
    };
  },
});
</script>

