<template>
  <q-card class="line-card p-20">
    <q-card-section>
      <div class="cards-title font-size-21">
        {{ $t('workflow_7_month_runs') }}
      </div>
      <div class="chart-container">
        <div v-if="loading || !isMounted" class="chart-loader">
          <q-spinner-dots color="primary" size="50px" />
        </div>
        <apexchart
          v-else
          type="area"
          height="200"
          :series="lineSeries"
          :options="chartOptions"
        />
      </div>
    </q-card-section>
  </q-card>
</template>

<script lang="ts">
import { defineComponent } from 'vue';
import VueApexCharts from 'vue3-apexcharts';

export default defineComponent({
  name: 'WorkflowLineChart',

  components: {
    apexchart: VueApexCharts,
  },

  props: {
    workflowCardSummary: {
      type: Object,
      required: false,
      default: null,
    },
    loading: {
      type: Boolean,
      default: false,
    },
  },

  data() {
    return {
      isMounted: false,
      lineSeries: [
        {
          name: 'Success',
          data: [0, 0, 0, 0, 0] as number[],
        },
        {
          name: 'Failures',
          data: [0, 0, 0, 0, 0] as number[],
        },
      ],
      categories: ['Jan', 'Feb', 'Mar', 'Apr', 'May'] as string[],
      // Initialize with valid defaults to prevent "Element not found" errors
      chartOptions: {
        chart: {
          id: 'flowRunsChart',
          toolbar: { show: false },
          background: 'transparent',
        },
        xaxis: {
          categories: ['Jan', 'Feb', 'Mar', 'Apr', 'May'],
        },
      } as any,
    };
  },

  mounted() {
    this.updateChartOptions();
    // Delay mounting flag to ensure DOM is ready
    this.$nextTick(() => {
      this.isMounted = true;
    });
  },

  watch: {
    workflowCardSummary: {
      handler(newVal) {
        if (newVal) {
          this.updateLineChartData(newVal);
        }
      },
      immediate: true,
      deep: true,
    },
    '$q.dark.isActive'() {
      this.updateChartOptions();
    },
    categories() {
      this.updateChartOptions();
    },
  },

  methods: {
    updateChartOptions() {
      const isDark = this.$q.dark.isActive;

      this.chartOptions = {
        chart: {
          id: 'flowRunsChart',
          toolbar: { show: false },
          background: 'transparent',
        },
        theme: {
          mode: isDark ? 'dark' : 'light',
        },
        xaxis: {
          categories: this.categories,
          labels: {
            style: {
              colors: isDark ? '#d2d2d2' : '#6b7280',
              fontSize: '12px',
            },
          },
        },
        yaxis: {
          labels: {
            style: {
              colors: isDark ? '#d2d2d2' : '#6b7280',
              fontSize: '12px',
            },
          },
        },
        stroke: {
          curve: 'smooth' as const,
          width: 2,
        },
        colors: ['#10b981', '#f87171'],
        fill: {
          type: 'gradient',
          gradient: {
            shade: isDark ? 'dark' : 'light',
            shadeIntensity: 0.7,
            inverseColors: false,
            opacityFrom: 0.7,
            opacityTo: 0.3,
            stops: [0, 90, 100],
            colorStops: [
              [
                {
                  offset: 0,
                  color: '#10b981',
                  opacity: 0.5,
                },
                {
                  offset: 100,
                  color: '#10b981',
                  opacity: 0.7,
                },
              ],
              [
                {
                  offset: 0,
                  color: '#f87171',
                  opacity: 0.5,
                },
                {
                  offset: 100,
                  color: '#f87171',
                  opacity: 0.7,
                },
              ],
            ],
          },
        },
        tooltip: {
          theme: isDark ? 'dark' : 'light',
          y: {
            formatter: (val: number) => `${Number(val)} runs`,
          },
        },
        grid: {
          show: true,
          borderColor: isDark ? '#4b5563' : '#e5e7eb',
          strokeDashArray: 4,
          xaxis: {
            lines: {
              show: false,
            },
          },
          yaxis: {
            lines: {
              show: true,
            },
          },
        },
        legend: {
          labels: {
            colors: isDark ? '#d2d2d2' : '#6b7280',
          },
        },
      };
    },

    updateLineChartData(summary: any) {
      // Generate last 7 months from current date
      const last7Months = this.getLast7Months();

      // Create a map of backend data by month key (YYYY-MM)
      const dataByMonth: Record<string, { success: number; failed: number }> = {};

      if (summary?.logs_by_count_filter?.length) {
        summary.logs_by_count_filter.forEach((item: any) => {
          const date = new Date(item.period_start);
          const monthKey = `${date.getFullYear()}-${String(date.getMonth() + 1).padStart(2, '0')}`;
          dataByMonth[monthKey] = {
            success: item.success || 0,
            // Only count actual errors and no_data, not failed_condition (which is intentional)
            failed: (item.error || 0) + (item.no_data || 0),
          };
        });
      }

      // Map data to last 7 months, filling with 0s for missing months
      const successData = last7Months.map(
        (month) => dataByMonth[month.key]?.success || 0,
      );
      const failedData = last7Months.map(
        (month) => dataByMonth[month.key]?.failed || 0,
      );

      this.categories = last7Months.map((month) => month.label);
      this.lineSeries[0].data = successData;
      this.lineSeries[1].data = failedData;
    },

    getLast7Months(): { key: string; label: string }[] {
      const months = [];
      const now = new Date();

      for (let i = 6; i >= 0; i--) {
        const date = new Date(now.getFullYear(), now.getMonth() - i, 1);
        months.push({
          key: `${date.getFullYear()}-${String(date.getMonth() + 1).padStart(2, '0')}`,
          label: date.toLocaleString('default', { month: 'short' }),
        });
      }

      return months;
    },
  },
});
</script>

