/**
 * URL-backed view state for the workflow list: search term, page, page size and
 * sort order. A fresh navigation carries no query and therefore starts clean.
 *
 * The query cannot be the only source: the workflowsdashboard breadcrumb in the
 * designer header navigates to the bare path, because BreadCrumb.vue builds its
 * links from route meta. So the state is also remembered per tab, and recalled
 * only when the previous route was a workflow detail.
 *
 * Page size goes through a PageSizeStore so it can move to the user-scoped
 * LocalStorage key the document dashboard uses: supply a store whose read()
 * consults LocalStorage and whose apply() returns the query unchanged.
 */

import { SessionStorage } from 'quasar';

export type SortDirection = 'asc' | 'desc';

export interface WorkflowListSort {
  field: string;
  direction: SortDirection;
}

export interface WorkflowListViewState {
  search: string;
  page: number;
  pageSize: number;
  sort: WorkflowListSort;
}

export const WORKFLOW_LIST_PAGE_SIZES: readonly number[] = [10, 20, 25, 50];

export const DEFAULT_WORKFLOW_LIST_PAGE_SIZE = 25;

// The Fields enum of GET /v3/workflow/dashboard. Neither it nor OrderBy is
// nullable and both default server-side, so the list has no unsorted state.
export const WORKFLOW_LIST_SORT_FIELDS: readonly string[] = [
  'name',
  'created_on',
  'last_modified_on',
];

export const DEFAULT_WORKFLOW_LIST_SORT: WorkflowListSort = {
  field: 'created_on',
  direction: 'desc',
};

export const SEARCH_PARAM = 'search';
export const PAGE_PARAM = 'page';
export const PAGE_SIZE_PARAM = 'size';
export const SORT_PARAM = 'sort';

const LIST_STATE_PARAMS: readonly string[] = [
  SEARCH_PARAM,
  PAGE_PARAM,
  PAGE_SIZE_PARAM,
  SORT_PARAM,
];

type QueryValue = string | string[] | null | undefined;

export type RouteQuery = Record<string, QueryValue>;
export type OutgoingQuery = Record<string, string>;

export interface PageSizeStore {
  read(query: RouteQuery): number | null;
  apply(query: OutgoingQuery, pageSize: number): OutgoingQuery;
}

// Guards two untrusted sources: the route query and the remembered state.
function firstValue(value: unknown): string {
  if (Array.isArray(value)) {
    return value[0] === null || value[0] === undefined ? '' : String(value[0]);
  }
  if (value === null || value === undefined) {
    return '';
  }
  return String(value);
}

function toPage(value: unknown): number {
  const page = Number(firstValue(value));
  if (!Number.isInteger(page) || page < 1) {
    return 1;
  }
  return page;
}

function toPageSize(value: unknown): number | null {
  const raw = firstValue(value);
  if (raw === '') {
    return null;
  }
  const pageSize = Number(raw);
  return WORKFLOW_LIST_PAGE_SIZES.includes(pageSize) ? pageSize : null;
}

function normaliseSort(field: unknown, direction: unknown): WorkflowListSort {
  const normalisedField = firstValue(field).trim().toLowerCase();
  const normalisedDirection = firstValue(direction).trim().toLowerCase();

  if (
    !WORKFLOW_LIST_SORT_FIELDS.includes(normalisedField) ||
    (normalisedDirection !== 'asc' && normalisedDirection !== 'desc')
  ) {
    return { ...DEFAULT_WORKFLOW_LIST_SORT };
  }
  return { field: normalisedField, direction: normalisedDirection };
}

function toSort(value: unknown): WorkflowListSort {
  const [field, direction] = firstValue(value).split(':');
  return normaliseSort(field, direction);
}

export function isDefaultSort(sort: WorkflowListSort): boolean {
  return (
    sort.field === DEFAULT_WORKFLOW_LIST_SORT.field &&
    sort.direction === DEFAULT_WORKFLOW_LIST_SORT.direction
  );
}

function sortParam(sort: WorkflowListSort): string | null {
  return isDefaultSort(sort) ? null : `${sort.field}:${sort.direction}`;
}

/**
 * The only two places that know about the control's "sort_" prefix. A cleared
 * direction normalises to the default, which is what the API applies anyway.
 */
export function readSortFromControls(
  sortByValue: unknown,
  sortDirectionValue: unknown,
): WorkflowListSort {
  return normaliseSort(
    sortByValue,
    firstValue(sortDirectionValue).replace('sort_', ''),
  );
}

export function sortDirectionControlValue(sort: WorkflowListSort): string {
  return `sort_${sort.direction}`;
}

export const urlPageSizeStore: PageSizeStore = {
  read(query: RouteQuery): number | null {
    return toPageSize(query[PAGE_SIZE_PARAM]);
  },

  apply(query: OutgoingQuery, pageSize: number): OutgoingQuery {
    const next = { ...query };
    if (pageSize === DEFAULT_WORKFLOW_LIST_PAGE_SIZE) {
      delete next[PAGE_SIZE_PARAM];
      return next;
    }
    next[PAGE_SIZE_PARAM] = String(pageSize);
    return next;
  },
};

export function readWorkflowListState(
  query: RouteQuery,
  pageSizeStore: PageSizeStore = urlPageSizeStore,
): WorkflowListViewState {
  return {
    search: firstValue(query[SEARCH_PARAM]),
    page: toPage(query[PAGE_PARAM]),
    pageSize: pageSizeStore.read(query) ?? DEFAULT_WORKFLOW_LIST_PAGE_SIZE,
    sort: toSort(query[SORT_PARAM]),
  };
}

/** Defaults are left out, which is what makes a fresh open reset by itself. */
export function buildWorkflowListQuery(
  state: WorkflowListViewState,
  currentQuery: RouteQuery = {},
  pageSizeStore: PageSizeStore = urlPageSizeStore,
): OutgoingQuery {
  const query: OutgoingQuery = {};

  // Params owned by other components, such as the dashboard's active tab.
  for (const [key, value] of Object.entries(currentQuery)) {
    if (LIST_STATE_PARAMS.includes(key)) {
      continue;
    }
    const single = firstValue(value);
    if (single !== '') {
      query[key] = single;
    }
  }

  if (state.search !== '') {
    query[SEARCH_PARAM] = state.search;
  }
  if (state.page > 1) {
    query[PAGE_PARAM] = String(state.page);
  }

  const sort = sortParam(state.sort);
  if (sort !== null) {
    query[SORT_PARAM] = sort;
  }

  return pageSizeStore.apply(query, state.pageSize);
}

/** For a caller that is leaving the list behind, such as a tab switch. */
export function stripWorkflowListParams(query: RouteQuery): OutgoingQuery {
  const kept: OutgoingQuery = {};
  for (const [key, value] of Object.entries(query)) {
    if (LIST_STATE_PARAMS.includes(key)) {
      continue;
    }
    const single = firstValue(value);
    if (single !== '') {
      kept[key] = single;
    }
  }
  return kept;
}

export function hasListStateParams(query: RouteQuery): boolean {
  return LIST_STATE_PARAMS.some((param) => firstValue(query[param]) !== '');
}

const WORKFLOW_DETAIL_BASE_PATHS: readonly string[] = [
  '/workflow_designer',
  '/advanced_workflow_designer',
  '/template_designer',
];

/**
 * The designer routes take an optional id, so a workflow that has not been
 * saved yet sits on the bare base path. That form counts as a designer too,
 * otherwise abandoning a new workflow drops the list state on the way back.
 * Matching the base exactly, or followed by a separator, keeps a sibling route
 * such as /workflow_designer_settings out.
 */
export function isWorkflowDetailPath(path: string | null | undefined): boolean {
  if (!path) {
    return false;
  }
  const pathWithoutQuery = path.split(/[?#]/)[0];
  return WORKFLOW_DETAIL_BASE_PATHS.some(
    (base) =>
      pathWithoutQuery === base || pathWithoutQuery.startsWith(`${base}/`),
  );
}

export interface ResolvedWorkflowListState {
  state: WorkflowListViewState;
  restoredFromMemory: boolean;
}

/**
 * The query wins whenever it carries anything, so back, reload and shared links
 * behave as plain URL state. Memory is only trusted when the previous route was a
 * designer, otherwise the side menu would resurrect an abandoned search.
 */
export function resolveWorkflowListState(input: {
  query: RouteQuery;
  previousPath: string | null | undefined;
  remembered: WorkflowListViewState | null;
  pageSizeStore?: PageSizeStore;
}): ResolvedWorkflowListState {
  const { query, previousPath, remembered, pageSizeStore } = input;

  if (hasListStateParams(query)) {
    return {
      state: readWorkflowListState(query, pageSizeStore),
      restoredFromMemory: false,
    };
  }

  if (remembered && isWorkflowDetailPath(previousPath)) {
    return { state: remembered, restoredFromMemory: true };
  }

  return {
    state: readWorkflowListState({}, pageSizeStore),
    restoredFromMemory: false,
  };
}

export const LIST_STATE_MEMORY_KEY = 'workflow_list_view_state';

export function rememberWorkflowListState(state: WorkflowListViewState): void {
  SessionStorage.set(LIST_STATE_MEMORY_KEY, state);
}

export function forgetWorkflowListState(): void {
  SessionStorage.remove(LIST_STATE_MEMORY_KEY);
}

export function recallWorkflowListState(): WorkflowListViewState | null {
  const stored = SessionStorage.getItem(LIST_STATE_MEMORY_KEY);
  if (!stored || typeof stored !== 'object') {
    return null;
  }

  const recalled = stored as Record<string, unknown>;
  const sort = (recalled.sort ?? {}) as Record<string, unknown>;
  return {
    search: firstValue(recalled.search),
    page: toPage(recalled.page),
    pageSize: toPageSize(recalled.pageSize) ?? DEFAULT_WORKFLOW_LIST_PAGE_SIZE,
    sort: normaliseSort(sort.field, sort.direction),
  };
}

/**
 * A restored page can point past the end of a narrowed result set. Refetching
 * from page 1 cannot loop, because page 1 never satisfies this.
 */
export function shouldFallBackToFirstPage(
  returnedEntryCount: number,
  page: number,
): boolean {
  return returnedEntryCount === 0 && page > 1;
}
